        'jira_blurb' => 'ടിക്കറ്റുകളിൽ നിന്ന് Jira ഇഷ്യൂകൾ ഉയർത്തുകയും FreeITSM വിട്ടുപോകാതെ അവയുടെ നില കാണുകയും ചെയ്യുക. Jira Cloud, Jira Data Center എന്നിവ രണ്ടും പ്രവർത്തിക്കും.',
        'jira_url_label' => 'Jira സൈറ്റ് URL',
        'azuredevops_blurb' => 'ടിക്കറ്റുകളിൽ നിന്ന് Azure DevOps വർക്ക് ഐറ്റങ്ങൾ ഉയർത്തുകയും FreeITSM വിട്ടുപോകാതെ അവയുടെ നില കാണുകയും ചെയ്യുക. Azure DevOps Services, Azure DevOps Server എന്നിവ പ്രവർത്തിക്കും.',
        'azuredevops_url_label' => 'ഓർഗനൈസേഷൻ URL',
        'field_resolved_means' => 'ഒരു വർക്ക് ഐറ്റം Resolved ആയി അടയാളപ്പെടുത്തുമ്പോൾ',
        'field_resolved_means_hint' => 'Azure DevOps-ന് ഒരു Resolved അവസ്ഥയുണ്ട്, അതായത് ഒരു ഡെവലപ്പർ അത് ശരിയാക്കിയെന്ന് കരുതുന്നു എന്നാൽ ആരും ഇതുവരെ പരിശോധിച്ചിട്ടില്ല. Bugs ഇത് ഉപയോഗിക്കുന്നു; user stories ഉപയോഗിക്കുന്നില്ല.',
        'resolved_in_progress' => 'ഇപ്പോഴും പുരോഗതിയിലാണെന്ന് കണക്കാക്കുക',
        'resolved_done' => 'പൂർത്തിയായി എന്ന് കണക്കാക്കുക',
        'one_connection' => '1 കണക്ഷൻ',
        'n_connections' => '{n} കണക്ഷനുകൾ',
        'no_connections' => 'ഇതുവരെ കണക്ഷനുകളൊന്നുമില്ല.',
        'connections_heading' => 'കണക്ഷനുകൾ',
        'connections_desc' => 'ഓരോ കണക്ഷനും നിങ്ങൾക്ക് ഇഷ്യൂകൾ ഉയർത്താൻ കഴിയുന്ന ഒരു സൈറ്റാണ്. വ്യത്യസ്ത ടീമുകളോ ക്ലയന്റുകളോ വെവ്വേറെ സൈറ്റുകൾ ഉപയോഗിക്കുന്നെങ്കിൽ ഒന്നിലധികം ചേർക്കുക.',
