        'field_email_hint' => 'Jira Cloud മാത്രം — API ടോക്കൺ ഏത് അക്കൗണ്ടിന്റേതാണോ അത്. Jira Data Center-ന് ശൂന്യമായി വിടുക, അതിന് സ്വന്തമായി ഒരു personal access token ഉപയോഗിക്കുന്നു.',
