        'company_shared' => 'എല്ലാ കമ്പനികളും',
        'company_hint' => 'നിങ്ങളുടെ സ്വന്തം ടീം ഉപയോഗിക്കുന്ന ട്രാക്കറിന് എല്ലാ കമ്പനികളും ആയി വിടുക. ആ ക്ലയന്റിലേക്ക് പരിമിതപ്പെടുത്താൻ ഒരു കമ്പനി തിരഞ്ഞെടുക്കുക — മറ്റ് കമ്പനികളിൽ നിന്നുള്ള ടിക്കറ്റുകൾ പിന്നെ അതിലേക്ക് എസ്കലേറ്റ് ചെയ്യാൻ കഴിയില്ല.',
