        'help_link' => '{name} എങ്ങനെ സജ്ജീകരിക്കാം',
        'mapping_help_link' => 'ഇവയുടെ അർത്ഥം ഉറപ്പില്ലേ?',
        'mapping_title' => 'മാപ്പിംഗ്',
        'mapping_intro' => '{name}-ൽ നിങ്ങളുടെ മൂല്യങ്ങളുടെ അർത്ഥം എന്താണെന്ന് തീരുമാനിക്കുക, അങ്ങനെ ഓരോ റൂളിലും ഒരു പ്രോജക്ട് കീ ടൈപ്പ് ചെയ്യേണ്ടിവരില്ല. ശൂന്യമായി വിട്ടത് അയക്കപ്പെടില്ല.',
        'map_projects' => 'ഇഷ്യൂകൾ ഏത് പ്രോജക്ടിലേക്ക് പോകുന്നു',
        'map_projects_hint' => 'ഒരു ഡിഫോൾട്ട് സജ്ജമാക്കുക, പിന്നെ ആവശ്യമുള്ളിടത്ത് അപവാദങ്ങൾ ചേർക്കുക. ഏറ്റവും നിർദ്ദിഷ്ടമായ റൂൾ ജയിക്കും: ഒരു വകുപ്പ് ഒരു കമ്പനിയെ തോൽപ്പിക്കും, ഒരു കമ്പനി ഡിഫോൾട്ടിനെ തോൽപ്പിക്കും.',
        'map_group_default' => 'ഡിഫോൾട്ട്',
        'map_group_dept' => 'വകുപ്പ് അനുസരിച്ചുള്ള അപവാദങ്ങൾ — ഇവ താഴെയുള്ള എല്ലാറ്റിനെയും തോൽപ്പിക്കും',
        'map_group_company' => 'കമ്പനി അനുസരിച്ചുള്ള അപവാദങ്ങൾ',
        'map_types' => 'ടിക്കറ്റ് തരം ഇഷ്യൂ തരമാകുന്നു',
        'map_types_hint' => 'ഇഷ്യൂ തരങ്ങൾ ഓരോ പ്രോജക്ടിനും വ്യത്യസ്തമാണ്, അതിനാൽ ഇവ നിങ്ങളുടെ ഡിഫോൾട്ട് പ്രോജക്ടിൽ നിന്നുള്ള നിർദ്ദേശങ്ങളാണ് — നിങ്ങൾക്ക് ഏത് മൂല്യവും ടൈപ്പ് ചെയ്യാം.',
        'map_priorities' => 'മുൻഗണന',
        'map_priorities_hint' => 'ഇവിടെ മനഃപൂർവ്വം ഒരു ഡിഫോൾട്ടും ഇല്ല: എല്ലാ ഇഷ്യൂവും അടിയന്തിരം എന്ന് അടയാളപ്പെടുത്തുന്നത് ആർക്കും സഹായകരമല്ല. മാപ്പ് ചെയ്യാത്ത ഒരു മുൻഗണന ഇപ്പോഴും വിവരണത്തിൽ ടെക്സ്റ്റ് ആയി പ്രത്യക്ഷപ്പെടും. ഒരു പ്രോജക്ട് ഒരു മുൻഗണന നിരസിച്ചാൽ ഇഷ്യൂ ഇപ്പോഴും ഉയർത്തപ്പെടും, മുൻഗണന ഇല്ലാതെ മാത്രം.',
        'map_default' => 'ബാക്കിയെല്ലാം',
        'map_none' => 'മാപ്പ് ചെയ്തിട്ടില്ല',
        'map_saved' => 'മാപ്പിംഗ് സംരക്ഷിച്ചു',
        'map_needs_verify' => 'ആദ്യം Database Verification പ്രവർത്തിപ്പിക്കുക — ഈ ഇൻസ്റ്റാളിൽ മാപ്പിംഗ് ടേബിൾ ഇതുവരെ നിലവിലില്ല.',
        'map_load_failed' => 'മാപ്പിംഗ് ലോഡ് ചെയ്യാൻ കഴിഞ്ഞില്ല.',
        'attach_label' => 'ടിക്കറ്റിന്റെ അറ്റാച്ച്മെന്റുകൾ {name}-ലേക്ക് അയക്കുക',
        'attach_hint' => 'ഒരു ബഗ് റിപ്പോർട്ടിൽ സ്ക്രീൻഷോട്ട് പലപ്പോഴും റിപ്പോർട്ട് തന്നെയാണ്. ഒരു ഇമെയിലിൽ ഉൾച്ചേർത്ത ചിത്രങ്ങൾ — സിഗ്നേച്ചറുകൾ, ലോഗോകൾ, ട്രാക്കിംഗ് പിക്സലുകൾ — ഒരിക്കലും അയക്കില്ല, ആരെങ്കിലും മനഃപൂർവ്വം അറ്റാച്ച് ചെയ്ത ഫയലുകൾ മാത്രം. വലിയ ഫയലുകൾ എസ്കലേഷൻ പരാജയപ്പെടുത്താതെ ഒഴിവാക്കപ്പെടും, എന്തെങ്കിലും അയക്കുന്നതിന് മുമ്പ് നിങ്ങൾക്ക് എപ്പോഴും ലിസ്റ്റ് കാണാം.',
        'inbound_label' => '{name}-ൽ നിന്നുള്ള അപ്ഡേറ്റുകൾ സ്വീകരിക്കുക',
        'inbound_hint' => '{name}-ൽ എഴുതിയ അഭിപ്രായങ്ങൾ ലിങ്ക് ചെയ്ത ടിക്കറ്റിൽ ഇന്റേണൽ കുറിപ്പുകളായി എത്തും. അവ ഒരിക്കലും അഭ്യർത്ഥിച്ചയാൾക്ക് കാണിക്കില്ല. ഇത് ഓൺ ചെയ്ത ശേഷമുള്ള ആദ്യ പരിശോധന ഒന്നും ഇംപോർട്ട് ചെയ്യില്ല — അത് തുടക്ക പോയിന്റ് മാത്രം അടയാളപ്പെടുത്തുന്നു, അതിനാൽ ഇത് ഓൺ ചെയ്യുന്നത് പഴയ അഭിപ്രായങ്ങളുടെ ബാക്ക്‌ലോഗ് തിരികെ കൊണ്ടുവരില്ല.',
        'test' => 'ടെസ്റ്റ്',
        'save_failed' => 'കണക്ഷൻ സംരക്ഷിക്കാൻ കഴിഞ്ഞില്ല.',
        'saved' => 'കണക്ഷൻ സംരക്ഷിച്ചു.',
        'deleted' => 'കണക്ഷൻ ഇല്ലാതാക്കി.',
        'delete_title' => 'കണക്ഷൻ ഇല്ലാതാക്കുക',
        'confirm_delete' => 'ഈ കണക്ഷൻ ഇല്ലാതാക്കണോ?',
        'confirm_delete_named' => '"{name}" കണക്ഷൻ ഇല്ലാതാക്കണോ? അതിലെ ഇഷ്യൂകളുമായി ഇതിനകം ലിങ്ക് ചെയ്ത ടിക്കറ്റുകൾ അവയുടെ ലിങ്കുകൾ നിലനിർത്തും.',
        'slack_blurb' => 'ഒരു Slack ചാനലിലെ സന്ദേശം ഒരു ടിക്കറ്റാക്കി മാറ്റുക, ത്രെഡ് വിട്ടുപോകാതെ ഇൻബോക്സിൽ നിന്ന് അതിന് മറുപടി നൽകുക.',
        'configured' => 'കോൺഫിഗർ ചെയ്തു',
        'not_configured' => 'സജ്ജീകരിച്ചിട്ടില്ല',
        'tika_blurb' => 'PDF-കൾ, പഴയ Office ഫയലുകൾ, സ്കാൻ ചെയ്ത ഡോക്യുമെന്റുകൾ എന്നിവയ്ക്കുള്ളിലെ ടെക്സ്റ്റ് വായിക്കുക, അങ്ങനെ അവ തിരയാൻ കഴിയും.',
        'tika_intro' => 'FreeITSM-നെ ഒരു ഡോക്യുമെന്റ്-റീഡിംഗ് സർവീസിലേക്ക് ചൂണ്ടിക്കാണിക്കുന്നു. Word, Excel, PowerPoint, പ്ലെയിൻ ടെക്സ്റ്റ് ഫയലുകൾ ഇത് കൂടാതെ തന്നെ ഇതിനകം തിരയാൻ കഴിയും; FreeITSM-ന് സ്വന്തമായി വായിക്കാൻ കഴിയാത്ത ഫോർമാറ്റുകൾ Tika ചേർക്കുന്നു.',
        'tika_security_title' => 'ഇത് നെറ്റ്‌വർക്കിൽ നിന്ന് മാറ്റി നിർത്തുക',
        'tika_security_body' => 'Tika-ക്ക് പാസ്‌വേഡോ ഏതെങ്കിലും തരത്തിലുള്ള ഓതന്റിക്കേഷനോ ഇല്ല: അതിലേക്ക് എത്താൻ കഴിയുന്ന എന്തും അയക്കുന്ന ഏത് ഫയലും വായിക്കും. ഈ സെർവറിന് മാത്രം അതുമായി സംസാരിക്കാൻ കഴിയുന്ന വിധത്തിൽ ഇത് പ്രവർത്തിപ്പിക്കുക — 127.0.0.1-ലേക്ക് ബൈൻഡ് ചെയ്ത്, അല്ലെങ്കിൽ ഒരു പ്രൈവറ്റ് കണ്ടെയ്നർ നെറ്റ്‌വർക്കിൽ — അതിന്റെ പോർട്ട് ഒരിക്കലും ഇന്റർനെറ്റിലേക്ക് തുറന്നിടരുത്.',
        'tika_connection' => 'കണക്ഷൻ',
        'tika_url_label' => 'വിലാസം',
        'tika_url_hint' => 'ഉദാഹരണത്തിന് http://127.0.0.1:9998. ഡോക്യുമെന്റ് റീഡിംഗ് ഓഫ് ചെയ്യാൻ ഇത് ശൂന്യമായി വിടുക; PDF-കൾ വായിക്കാൻ കഴിയാത്തവയായി ലിസ്റ്റ് ചെയ്യപ്പെടും.',
        'tika_timeout_label' => 'ടൈംഔട്ട് (സെക്കൻഡുകൾ)',
        'tika_timeout_hint' => 'ഒരു ഡോക്യുമെന്റിനായി എത്ര നേരം കാത്തിരിക്കണം. സ്കാൻ ചെയ്ത പേജുകൾ സാധാരണ ടെക്സ്റ്റിനേക്കാൾ വളരെ കൂടുതൽ സമയമെടുക്കും.',
