        'tika_saved_off' => 'സംരക്ഷിച്ചു. ഡോക്യുമെന്റ് റീഡിംഗ് ഓഫ് ചെയ്തിരിക്കുന്നു.',
        'tika_requeued' => 'നേരത്തെ വായിക്കാൻ കഴിയാതിരുന്ന {n} അറ്റാച്ച്മെന്റുകൾ ക്യൂവിലാക്കി.',
        'tika_pending' => '{n} അറ്റാച്ച്മെന്റുകൾ വായിക്കാൻ കാത്തിരിക്കുന്നു.',
        'tika_formats' => 'എന്താണ് വായിക്കുന്നത്',
        'tika_without' => 'Tika ഇല്ലാതെ ഇതിനകം വായിച്ചത്',
        'tika_with' => 'Tika ചേർത്തത്',
        'tika_legacy_office' => 'പഴയ Office ഫയലുകൾ (.doc, .xls, .ppt)',
        'tika_scanned' => 'സ്കാൻ ചെയ്ത ഡോക്യുമെന്റുകളും ടെക്സ്റ്റിന്റെ ഫോട്ടോകളും, കാരക്ടർ റെക്കഗ്നിഷൻ വഴി',
        'tika_running' => 'ഒന്ന് പ്രവർത്തിപ്പിക്കൽ',
        'tika_running_body' => 'FreeITSM Tika ഇൻസ്റ്റാൾ ചെയ്യുകയോ കൈകാര്യം ചെയ്യുകയോ ചെയ്യുന്നില്ല. നിങ്ങൾക്ക് അനുയോജ്യമായ ഇടത്ത് ഇത് സ്വയം പ്രവർത്തിപ്പിച്ച്, അതിന്റെ വിലാസം മുകളിൽ നൽകുക. Docker ഉപയോഗിച്ച് അതൊരു കമാൻഡ് മാത്രമാണ്:',
        'tika_image_note' => '-full ഇമേജ് ഉപയോഗിക്കുക. ചെറിയതിന് കാരക്ടർ റെക്കഗ്നിഷൻ ഇല്ല, അതിനാൽ സ്കാൻ ചെയ്ത ഡോക്യുമെന്റുകൾ ശൂന്യമായി തിരികെ വരും.',
        'slack_workspaces' => 'Slack വർക്ക്സ്പേസുകൾ',
        'slack_workspaces_desc' => 'ഓരോന്നും നിങ്ങളുടെ സ്വന്തം വർക്ക്സ്പേസിൽ ഇൻസ്റ്റാൾ ചെയ്യുന്ന ഒരു Slack ആപ്പാണ്. FreeITSM നിങ്ങളുടെ Slack ട്രാഫിക് ഒരിക്കലും കാണില്ല — ആപ്പ് ഈ സെർവറുമായി നേരിട്ട് സംസാരിക്കുന്നു.',
        'slack_col_channel' => 'നിരീക്ഷിക്കുന്നത്',
        'slack_any_channel' => 'ഇത് ക്ഷണിക്കപ്പെട്ട ഏത് ചാനലും',
        'slack_empty' => 'ഇതുവരെ Slack വർക്ക്സ്പേസുകളൊന്നുമില്ല. ഒന്ന് ചേർത്ത്, Slack-ൽ നിന്ന് അതിന്റെ ആപ്പ് ശേഖരിക്കുക.',
        'slack_needs_setup' => 'സജ്ജീകരണം ആവശ്യമാണ്',
        'slack_add_title' => 'ഒരു Slack വർക്ക്സ്പേസ് ചേർക്കുക',
        'slack_edit_title' => 'Slack വർക്ക്സ്പേസ് എഡിറ്റ് ചെയ്യുക',
        'slack_name_hint' => 'ഈ ലിസ്റ്റിൽ മാത്രം ഉപയോഗിക്കുന്നു, കൂടാതെ നിങ്ങൾ സൃഷ്ടിക്കുന്ന Slack ആപ്പിന്റെ പേരായും.',
        'slack_name_required' => 'ഈ വർക്ക്സ്പേസിന് ഒരു പേര് നൽകുക.',
        'slack_unchanged' => 'മാറ്റമില്ല — നിലനിർത്താൻ ശൂന്യമായി വിടുക',
        'slack_bot_token' => 'Bot user OAuth token',
        'slack_bot_token_hint' => 'നിങ്ങളുടെ Slack ആപ്പിൽ, OAuth &amp; Permissions-ന് കീഴിൽ. xoxb- എന്ന് തുടങ്ങുന്നു. ആപ്പ് ഇൻസ്റ്റാൾ ചെയ്ത ശേഷം ഇത് ലഭിക്കും, അതിനാൽ ആദ്യ സേവിൽ ഇത് ശൂന്യമായി വിടുക.',
        'slack_signing_secret' => 'Signing secret',
        'slack_signing_secret_hint' => 'നിങ്ങളുടെ Slack ആപ്പിൽ, Basic Information-ന് കീഴിൽ. ഒരു സന്ദേശം ശരിക്കും Slack-ൽ നിന്നാണ് വന്നതെന്ന് FreeITSM തെളിയിക്കുന്നത് ഇങ്ങനെയാണ്, അതിനാൽ ഇത് സജ്ജമാക്കുന്നത് വരെ ഒന്നും സ്വീകരിക്കില്ല.',
        'slack_watch_channel' => 'ഈ ചാനൽ മാത്രം നിരീക്ഷിക്കുക',
        'slack_watch_channel_hint' => 'C08ABCDEF പോലുള്ള ഒരു Slack ചാനൽ ID. ആപ്പ് ക്ഷണിക്കപ്പെട്ട എല്ലാ ചാനലിൽ നിന്നും ടിക്കറ്റ് ഉയർത്താൻ ശൂന്യമായി വിടുക — ഇത് തിരക്കുള്ള ചാനലിൽ ഓരോ സന്ദേശത്തിനും ഒരു ടിക്കറ്റ് എന്നാണർത്ഥം, അതിനാൽ മിക്കവരും ഇവിടെ ഒരു ഹെൽപ്പ് ചാനൽ പേരിടുന്നു.',
        'slack_company_shared' => 'പങ്കിട്ടത് — അയച്ചയാൾ അനുസരിച്ച് തീരുമാനിക്കുക',
        'slack_company_hint' => 'ഈ വർക്ക്സ്പേസ് ഒരു കമ്പനിയിലേക്ക് പിൻ ചെയ്യുക, അല്ലെങ്കിൽ പങ്കിട്ടതായി വിട്ട് അയച്ചയാൾ തീരുമാനിക്കട്ടെ.',
        'slack_delete_confirm' => '"{name}" Slack വർക്ക്സ്പേസ് ഇല്ലാതാക്കണോ? അതിൽ നിന്ന് ഇതിനകം ഉയർത്തിയ ടിക്കറ്റുകൾ അവയുടെ ചരിത്രം നിലനിർത്തും; പുതിയ സന്ദേശങ്ങൾ മാത്രം എത്തുന്നത് നിലയ്ക്കും.',
        'slack_diag_title' => 'Slack ഹെൽത്ത് ചെക്ക്',
        'slack_diag_desc' => 'നിശബ്ദമായി തെറ്റാകാവുന്ന എല്ലാം പരിശോധിക്കുന്നു — ടോക്കൺ പ്രവർത്തിക്കുന്നുണ്ടോ എന്ന് മാത്രമല്ല. ഓരോ ഫലവും അതിനെക്കുറിച്ച് എന്ത് ചെയ്യണമെന്ന് പറയുന്നു.',
        'slack_diag_running' => 'പരിശോധിക്കുന്നു — ഇത് Slack-നോടും നിങ്ങളുടെ സ്വന്തം പബ്ലിക് വിലാസത്തോടും സംസാരിക്കുന്നു, അതിനാൽ കുറച്ച് സെക്കൻഡ് കാത്തിരിക്കുക…',
        'slack_diag_rerun' => 'വീണ്ടും പ്രവർത്തിപ്പിക്കുക',
        'slack_diag_all_ok' => 'എല്ലാം ശരിയാണ്. നിരീക്ഷിക്കുന്ന Slack ചാനലിൽ പോസ്റ്റ് ചെയ്യുന്ന സന്ദേശങ്ങൾ ടിക്കറ്റുകളാകും, മറുപടികൾ ത്രെഡിലേക്ക് തിരികെ പോകും.',
        'slack_diag_some_warn' => 'പ്രവർത്തിക്കുന്നു, അറിഞ്ഞിരിക്കേണ്ട ഒരു കാര്യമുണ്ട്. താഴെയുള്ളത് ടിക്കറ്റുകൾ എത്തുന്നത് തടയില്ല, പക്ഷേ വായിക്കേണ്ടതാണ്.',
        'slack_diag_some_fail' => 'എന്തോ തെറ്റാണ്, സന്ദേശങ്ങൾ എത്തില്ല. താഴെയുള്ള പരാജയപ്പെട്ട പരിശോധനകൾ എന്ത് ചെയ്യണമെന്ന് പറയുന്നു.',
        'slack_app_title' => 'Slack ആപ്പ്',
        'slack_copy_manifest' => 'മാനിഫെസ്റ്റ് പകർത്തുക',
        'slack_scopes_heading' => 'ആപ്പിന് ചെയ്യാൻ അനുവാദമുള്ളത്',
        'slack_scopes_desc' => 'ആപ്പ് അംഗീകരിക്കുമ്പോൾ നിങ്ങളുടെ Slack അഡ്മിൻ ഈ ലിസ്റ്റ് കാണും. ചാനലുകൾ സൃഷ്ടിക്കാനോ ആളുകളെ ക്ഷണിക്കാനോ ക്ഷണിക്കപ്പെടാത്ത എവിടെയെങ്കിലും പോസ്റ്റ് ചെയ്യാനോ ഇവിടെ ഒന്നും അനുവദിക്കുന്നില്ല.',
        'slack_step1' => 'Slack-ൽ, <strong>api.slack.com/apps</strong>-ലേക്ക് പോയി <strong>Create New App → From a manifest</strong> തിരഞ്ഞെടുക്കുക. സർവീസ് ഡെസ്ക് വേണ്ട വർക്ക്സ്പേസ് തിരഞ്ഞെടുക്കുക.',
        'slack_step2' => 'ഈ മാനിഫെസ്റ്റ് പേസ്റ്റ് ചെയ്യുക. ഇത് പേര്, അനുമതികൾ, Slack സന്ദേശങ്ങൾ അയക്കുന്ന വിലാസം എന്നിവ സജ്ജമാക്കുന്നു, അതിനാൽ കൈകൊണ്ട് ടിക് ചെയ്യേണ്ടതൊന്നുമില്ല.',
        'slack_step3' => '<strong>Install to Workspace</strong> ക്ലിക്ക് ചെയ്ത് അംഗീകരിക്കുക. പിന്നെ <strong>Bot User OAuth Token</strong>-ഉം <strong>Signing Secret</strong>-ഉം ഇവിടെയുള്ള Edit ഫോമിലേക്ക് തിരികെ പകർത്തുക — Slack ടോക്കൺ വീണ്ടും കാണിക്കില്ല. <strong>Slack ഒരു മഞ്ഞ &ldquo;Reinstall to Workspace&rdquo; ബാനർ കാണിച്ചാൽ, ആദ്യം അത് ക്ലിക്ക് ചെയ്യുക</strong> — അല്ലെങ്കിൽ ടോക്കണിന് അതിന്റെ മിക്ക അനുമതികളും നഷ്ടപ്പെടും, ടിക്കറ്റുകൾ അയച്ചയാളുടെ പേരില്ലാതെ എത്തും.',
        'slack_step4' => 'താഴെയുള്ള റിക്വസ്റ്റ് URL <strong>Event Subscriptions</strong>-ന് കീഴിൽ Slack കാണിക്കുന്നതുമായി പൊരുത്തപ്പെടുന്നുണ്ടോ എന്ന് പരിശോധിക്കുക. ആപ്പ് സേവ് ചെയ്യുന്ന നിമിഷം Slack ഇത് പരിശോധിക്കുന്നു, അതിനാൽ ഈ സെർവർ ഇന്റർനെറ്റിൽ നിന്ന് എത്തിച്ചേരാവുന്നതായിരിക്കണം.',
        'slack_step5' => 'Slack-ൽ, നിരീക്ഷിക്കേണ്ട ചാനലിലേക്ക് ആപ്പിനെ ക്ഷണിക്കുക: <strong>/invite @YourApp</strong>. അതില്ലാത്ത ഒരു ചാനൽ വായിക്കാൻ കഴിയില്ല.',
    ],
    'branding' => [
        'title' => 'ബ്രാൻഡിംഗ്',
        'subtitle' => 'സ്ഥാപനത്തിന്റെ ലോഗോ, ആളുകൾ എത്തിച്ചേരുന്ന പേജ്, ഡയഗ്രമുകളിലും എക്സ്പോർട്ട് ചെയ്ത രേഖകളിലും ഉപയോഗിക്കുന്ന സ്ഥിരസ്ഥിതി ഹെഡർ/ഫൂട്ടർ ടെക്സ്റ്റ് എന്നിവ സജ്ജമാക്കുക',
