        'warning' => '<strong>ഇത് ഓണാക്കുന്നതിന് മുൻപ് വായിക്കുക.</strong> സംഭവങ്ങളുടെ തലക്കെട്ടുകൾ എഴുതിയിരിക്കുന്നത് നിങ്ങളുടെ ടീമിന് വേണ്ടിയാണ്, ഉപഭോക്താക്കൾക്ക് വേണ്ടിയല്ല &mdash; എൻഡ് യൂസർമാർ അവ വായിക്കാൻ തുടങ്ങുന്നതിന് മുൻപ് നിങ്ങളുടേത് എന്താണ് പറയുന്നതെന്ന് പരിശോധിക്കുക. വ്യക്തമായി <strong>എക്സ്റ്റേണൽ</strong> എന്ന് അടയാളപ്പെടുത്തിയ അപ്ഡേറ്റുകൾ മാത്രമേ എപ്പോഴും കാണിക്കൂ; ഈ ഫീച്ചർ വരുന്നതിന് മുൻപ് എഴുതിയതെല്ലാം ഇന്റേണൽ ആണ്, അതായി തുടരും.',
