        'subtitle' => 'യാഥാർത്ഥ്യബോധമുള്ള സാമ്പിൾ ഡാറ്റ മൊഡ്യൂൾ അനുസരിച്ച് ഇംപോർട്ട് ചെയ്യുക. ആദ്യം Core ഇംപോർട്ട് ചെയ്യുക, എന്നിട്ട് ഏതെല്ലാം മൊഡ്യൂളുകൾ പോപ്പുലേറ്റ് ചെയ്യണമെന്ന് തിരഞ്ഞെടുക്കുക.',
