        'warning_text' => 'ഒരു മൊഡ്യൂൾ ഇംപോർട്ട് ചെയ്യുന്നത് കഴിഞ്ഞ തവണ അത് സൃഷ്ടിച്ച സാമ്പിൾ റെക്കോർഡുകൾ നീക്കം ചെയ്ത് ഒരു പുതിയ സെറ്റ് ചേർക്കുന്നു. നിങ്ങളുടെ സ്വന്തം റെക്കോർഡുകൾ തൊടില്ല — ഈ ഇംപോർട്ടർ സൃഷ്ടിച്ച വരികൾ മാത്രമേ നീക്കം ചെയ്യൂ.',
        'untagged_strong' => 'ഈ ഇൻസ്റ്റലേഷനിൽ മുമ്പത്തെ ഒരു പതിപ്പിൽ നിന്നുള്ള ഡെമോ ഡാറ്റയുണ്ട്.',
        'untagged_text' => 'സാമ്പിൾ വരികൾ അങ്ങനെ അടയാളപ്പെടുത്തുന്നതിന് മുമ്പാണ് ഇത് ഇംപോർട്ട് ചെയ്തത്, അതിനാൽ ഇവിടെ നിന്ന് ഇത് തിരിച്ചറിയാനോ നീക്കം ചെയ്യാനോ കഴിയില്ല. വീണ്ടും ഇംപോർട്ട് ചെയ്താൽ, മാറ്റിസ്ഥാപിക്കുന്നതിന് പകരം അതിനൊപ്പം രണ്ടാമതൊരു കോപ്പി കൂടി ചേർക്കും. വൃത്തിയുള്ള ഒരു സെറ്റ് വേണമെങ്കിൽ ആദ്യം പഴയ സാമ്പിൾ റെക്കോർഡുകൾ കൈകൊണ്ട് നീക്കം ചെയ്യുക.',
        'tip_text_prefix' => 'രണ്ടും ഇംപോർട്ട് ചെയ്യുക',
        'tip_text_and' => 'ഒപ്പം',
