        'import_confirm' => '{module} ഡെമോ ഡാറ്റ ഇംപോർട്ട് ചെയ്യണോ? ഈ ഇൻസ്റ്റലേഷനിലേക്ക് സാമ്പിൾ റെക്കോർഡുകൾ ചേർക്കും. നിങ്ങളുടെ സ്വന്തം റെക്കോർഡുകളെ ഇത് ബാധിക്കില്ല.',
        'reimport_title' => 'ഡെമോ ഡാറ്റ മാറ്റിസ്ഥാപിക്കുക',
        'reimport_confirm' => '{module} ഡെമോ ഡാറ്റ മാറ്റിസ്ഥാപിക്കണോ? കഴിഞ്ഞ ഇംപോർട്ടിലെ സാമ്പിൾ റെക്കോർഡുകൾ നീക്കം ചെയ്ത് ഒരു പുതിയ സെറ്റ് ചേർക്കും. നിങ്ങളുടെ സ്വന്തം റെക്കോർഡുകളെ ഇത് ബാധിക്കില്ല.',
