    'encryption' => [
        'title' => 'എൻക്രിപ്ഷൻ',
        'subtitle' => 'സ്ഥിതി ചെയ്യുന്ന സെൻസിറ്റീവ് ഡാറ്റ സംരക്ഷിക്കാൻ ഉപയോഗിക്കുന്ന എൻക്രിപ്ഷൻ കീ മാനേജ് ചെയ്യുക',
        'checking' => 'എൻക്രിപ്ഷൻ നില പരിശോധിക്കുന്നു...',
        'how_heading' => 'എൻക്രിപ്ഷൻ എങ്ങനെ പ്രവർത്തിക്കുന്നു',
        'how_point1' => 'API കീകൾ, vCenter ക്രെഡൻഷ്യലുകൾ, മെയിൽബോക്സ് കണക്ഷൻ വിവരങ്ങൾ എന്നിങ്ങനെ ഡാറ്റാബേസിൽ സൂക്ഷിച്ചിട്ടുള്ള സെൻസിറ്റീവ് ഡാറ്റ സംരക്ഷിക്കാൻ FreeITSM {strong} ഓതന്റിക്കേറ്റഡ് എൻക്രിപ്ഷൻ ഉപയോഗിക്കുന്നു.',
        'how_point1_strong' => 'AES-256-GCM',
        'how_point2' => 'എൻക്രിപ്ഷൻ കീ 64 അക്ഷരങ്ങളുള്ള ഒരു ഹെക്സ് സ്ട്രിംഗ് ആണ് (256 ബിറ്റ്), അത് {strong} ഒരു ഫയലിൽ സൂക്ഷിച്ചിരിക്കുന്നു, അതിനാൽ ഒരു ബ്രൗസർ വഴി ഇത് ആക്സസ് ചെയ്യാൻ കഴിയില്ല.',
        'how_point2_strong' => 'വെബ് റൂട്ടിന് പുറത്ത്',
        'how_point3' => 'കീ ഫയലിന്റെ സ്ഥാനം:',
        'how_point4' => 'ഡാറ്റാബേസിലെ എൻക്രിപ്റ്റ് ചെയ്ത മൂല്യങ്ങൾക്ക് മുന്നിൽ {enc} ഉണ്ടാകും, തുടർന്ന് base64-എൻകോഡ് ചെയ്ത സൈഫർടെക്സ്റ്റ്. എൻക്രിപ്റ്റ് ചെയ്യാത്ത മൂല്യങ്ങൾ അതേപടി വിടും, ഇത് ക്രമേണയുള്ള മൈഗ്രേഷൻ സാധ്യമാക്കുന്നു.',
        'backup_strong' => 'നിങ്ങളുടെ എൻക്രിപ്ഷൻ കീ ബാക്കപ്പ് ചെയ്യുക.',
        'backup_text' => 'കീ നഷ്ടപ്പെട്ടാൽ, അതുപയോഗിച്ച് എൻക്രിപ്റ്റ് ചെയ്ത ഏത് ഡാറ്റയും വീണ്ടെടുക്കാൻ കഴിയില്ല. ഈ സെർവറിന് പുറത്ത് സുരക്ഷിതമായ എവിടെയെങ്കിലും ഒരു കോപ്പി സൂക്ഷിക്കുക.',
        'whats_heading' => 'എന്താണ് എൻക്രിപ്റ്റ് ചെയ്തിരിക്കുന്നത്',
        'group_settings' => 'സിസ്റ്റം ക്രമീകരണങ്ങൾ',
        'group_mailbox' => 'മെയിൽബോക്സ് കണക്ഷനുകൾ',
        'status_ok_title' => 'എൻക്രിപ്ഷൻ ക്രമീകരിച്ചിട്ടുണ്ട്',
        'status_ok_detail' => 'എൻക്രിപ്ഷൻ കീ {path} എന്നതിൽ ഉണ്ട്, സാധുവുമാണ്. AES-256-GCM ഉപയോഗിച്ച് സെൻസിറ്റീവ് ഡാറ്റ എൻക്രിപ്റ്റ് ചെയ്യപ്പെടുന്നു.',
        'status_invalid_title' => 'അസാധുവായ എൻക്രിപ്ഷൻ കീ',
        'status_invalid_detail' => '{path} എന്നതിൽ ഒരു കീ ഫയൽ കണ്ടെത്തി, പക്ഷേ അത് സാധുവായ 64 അക്ഷരങ്ങളുള്ള ഹെക്സ് സ്ട്രിംഗ് അല്ല. കീ കൃത്യമായി 64 ഹെക്സാഡെസിമൽ അക്ഷരങ്ങൾ ആയിരിക്കണം (256 ബിറ്റ്).',
        'generate_valid' => 'സാധുവായ കീ സൃഷ്ടിക്കുക',
        'status_missing_title' => 'എൻക്രിപ്ഷൻ കീ കണ്ടെത്തിയില്ല',
        'status_missing_detail' => '{path} എന്നതിൽ ഒരു എൻക്രിപ്ഷൻ കീ ഫയലും ഇല്ല. ഒരു കീ സൃഷ്ടിക്കുന്നതുവരെ സെൻസിറ്റീവ് ഡാറ്റ എൻക്രിപ്റ്റ് ചെയ്യാൻ കഴിയില്ല. സ്വയമേവ ഒന്ന് സൃഷ്ടിക്കാൻ താഴെയുള്ള ബട്ടൺ ക്ലിക്ക് ചെയ്യുക.',
        'generate' => 'എൻക്രിപ്ഷൻ കീ സൃഷ്ടിക്കുക',
