    'docker' => [
        'title' => 'Docker',
        'subtitle' => 'Docker-ൽ പ്രവർത്തിക്കുന്ന FreeITSM-ൽ HTTPS ഓണാക്കുക',
        'not_container' => 'ഈ പേജ് Docker ഇമേജിൽ പ്രവർത്തിക്കുന്ന FreeITSM-നുള്ളതാണ്, ഈ ഇൻസ്റ്റലേഷൻ അങ്ങനെയല്ല. പകരം നിങ്ങളുടെ വെബ് സെർവറിൽ (Apache, IIS അല്ലെങ്കിൽ nginx) HTTPS സജ്ജമാക്കുക.',
        'no_openssl' => 'PHP-യുടെ openssl എക്സ്റ്റൻഷൻ ലോഡ് ചെയ്തിട്ടില്ല, അതിനാൽ സർട്ടിഫിക്കറ്റ് ഉണ്ടാക്കാനാവില്ല.',
        'old_image_title' => 'ഈ കണ്ടെയ്നർ HTTPS പിന്തുണയ്ക്ക് മുമ്പുള്ളതാണ്',
        'old_image_body' => 'ആദ്യം ഏറ്റവും പുതിയ FreeITSM ഇമേജിലേക്ക് അപ്ഡേറ്റ് ചെയ്യുക, എന്നിട്ട് ഈ പേജിലേക്ക് മടങ്ങിവരിക. സോഴ്സിൽ നിന്നാണ് ബിൽഡ് ചെയ്യുന്നതെങ്കിൽ, FreeITSM ഫോൾഡറിൽ {cmd} പ്രവർത്തിപ്പിക്കുക.',
        'proxy_note' => 'ഈ കണ്ടെയ്നർ ഒരു റിവേഴ്സ് പ്രോക്സിക്ക് പിന്നിലാണ് സജ്ജമാക്കിയിരിക്കുന്നത് (TRUST_PROXY_HTTPS ഓണാണ്). HTTPS സാധാരണയായി പ്രോക്സി കൈകാര്യം ചെയ്യും, അതിനാൽ ഈ പേജ് നിങ്ങൾക്ക് ആവശ്യമുണ്ടാകില്ല.',
        'not_persisted_title' => 'ആദ്യം നിങ്ങളുടെ Docker സജ്ജീകരണത്തിൽ ഒരു മാറ്റം',
        'not_persisted_body' => 'ഒരു സർട്ടിഫിക്കറ്റ് സുരക്ഷിതമായി സൂക്ഷിക്കാൻ ഈ കണ്ടെയ്നറിന് ഇടമില്ല: അടുത്ത അപ്ഡേറ്റ് അത് ഇല്ലാതാക്കും. നിങ്ങളുടെ docker-compose.yml ഉള്ള ഫോൾഡറിൽ, താഴെയുള്ള ടെക്സ്റ്റ് അടങ്ങിയ {file} എന്ന പേരിൽ ഒരു ഫയൽ ഉണ്ടാക്കുക. ആ ഫയൽ ഇതിനകം ഉണ്ടെങ്കിൽ, ഈ വരികൾ അതിലേക്ക് ചേർക്കുക.',
        'not_persisted_then' => 'എന്നിട്ട് അതേ ഫോൾഡറിൽ {cmd} പ്രവർത്തിപ്പിച്ച് ഈ പേജ് റീലോഡ് ചെയ്യുക.',
        'status_off_title' => 'HTTPS ഓഫാണ്',
        'status_off_body' => 'FreeITSM സാധാരണ HTTP വഴി മാത്രമേ ലഭ്യമാകൂ. HTTPS ഓണാക്കാൻ താഴെ ഒരു സർട്ടിഫിക്കറ്റ് ഉണ്ടാക്കുക.',
        'status_on_title' => 'HTTPS ഓണാണ്',
        'status_on_body' => '{host}-നുള്ള സർട്ടിഫിക്കറ്റ് ഉപയോഗത്തിലുണ്ട്, {date} വരെ സാധുവാണ്.',
        'status_broken_title' => 'സർട്ടിഫിക്കറ്റ് ഫയലുകൾ പൊരുത്തപ്പെടുന്നില്ല',
        'status_broken_body' => 'ഡിസ്കിലെ സർട്ടിഫിക്കറ്റും അതിന്റെ കീയും പരസ്പരം ചേരുന്നില്ല, അതിനാൽ കണ്ടെയ്നർ സാധാരണ HTTP-യിൽ തുടരുന്നു. പുതിയ ജോടി ഉണ്ടാക്കാൻ താഴെ Generate അമർത്തുക.',
        'status_restart_title' => 'പൂർത്തിയാക്കാൻ കണ്ടെയ്നർ റീസ്റ്റാർട്ട് ചെയ്യുക',
        'status_restart_body' => '{host}-നുള്ള സർട്ടിഫിക്കറ്റ് തയ്യാറാണ്, പക്ഷേ കണ്ടെയ്നർ ഇപ്പോഴും അത് ഇല്ലാതെയാണ് പ്രവർത്തിക്കുന്നത്. നിങ്ങളുടെ docker-compose.yml ഉള്ള ഫോൾഡറിൽ {cmd} പ്രവർത്തിപ്പിക്കുക.',
        'form_heading' => 'സർട്ടിഫിക്കറ്റ്',
        'browsing_at' => 'നിങ്ങൾ FreeITSM-ൽ എത്തുന്നത് {address} വഴിയാണ്.',
        'host_label' => 'ആളുകൾ ടൈപ്പ് ചെയ്യുന്ന പേര്',
        'host_help' => 'ഉദാഹരണത്തിന് freeitsm.internal. .internal-ൽ അവസാനിക്കുന്ന പേര് ഒരു കമ്പനി നെറ്റ്‌വർക്കിനുള്ളിൽ ഉപയോഗിക്കാൻ സുരക്ഷിതമാണ്. ചില PC-കൾ മറ്റ് കാര്യങ്ങൾക്കായി മാറ്റിവയ്ക്കുന്ന .local ഒഴിവാക്കുക.',
        'ip_label' => 'സെർവർ IP വിലാസം',
        'ip_help' => 'PC-കൾ കാണുന്ന പ്രകാരം Docker പ്രവർത്തിപ്പിക്കുന്ന മെഷീന്റെ വിലാസം. IP വഴി ഈ പേജിൽ എത്തുമ്പോൾ നിങ്ങളുടെ അഡ്രസ് ബാറിൽ നിന്ന് ഇത് സ്വയം പൂരിപ്പിക്കും. ഓപ്ഷണലാണ്, പക്ഷേ ഇത് IP വഴിയും HTTPS പ്രവർത്തിക്കാൻ സഹായിക്കും.',
        'generate' => 'സൃഷ്ടിക്കുക',
        'generating' => 'സൃഷ്ടിക്കുന്നു...',
        'local_warning' => '.local-ൽ അവസാനിക്കുന്ന പേരുകൾ നെറ്റ്‌വർക്കിലെ മറ്റ് ഉപകരണങ്ങളുമായി ഏറ്റുമുട്ടാം. പകരം .internal ഉപയോഗിക്കുക.',
        'confirm_new_ca' => 'പേരോ IP-യോ മാറ്റുന്നത് ഒരു പുതിയ അതോറിറ്റി സർട്ടിഫിക്കറ്റ് ഉണ്ടാക്കും. പഴയതിനെ വിശ്വസിച്ചിരുന്ന ഓരോ PC-യിലും പുതിയത് ഇൻസ്റ്റാൾ ചെയ്യേണ്ടി വരും. തുടരണോ?',
        'err_invalid_host' => 'അത് സാധുവായ പേരല്ല. അക്ഷരങ്ങൾ, അക്കങ്ങൾ, ഹൈഫനുകൾ, ഡോട്ടുകൾ എന്നിവ മാത്രം ഉപയോഗിക്കുക, ഉദാഹരണത്തിന് freeitsm.internal.',
        'err_invalid_ip' => 'അത് സാധുവായ IP വിലാസമല്ല.',
        'err_not_persisted' => 'ആദ്യം ഈ പേജിന്റെ മുകളിലുള്ള Docker മാറ്റം വരുത്തുക.',
        'err_generic' => 'സർട്ടിഫിക്കറ്റ് ഉണ്ടാക്കാനായില്ല: {error}',
        'steps_heading' => 'അടുത്തതായി ചെയ്യേണ്ടത്',
        'step_dns_title' => 'പേര് സെർവറിലേക്ക് ചൂണ്ടുക',
        'step_dns_body' => '{host} എന്നാൽ {ip} ആണെന്ന് PC-കൾ അറിയണം. ഏറ്റവും നല്ല വഴി നിങ്ങളുടെ നെറ്റ്‌വർക്കിന്റെ DNS സെർവറിൽ ഒരു DNS റെക്കോർഡ് ഉണ്ടാക്കുന്നതാണ് (Windows ഡൊമെയ്നിൽ DNS Manager-ൽ; ചെറിയ നെറ്റ്‌വർക്കിൽ പലപ്പോഴും റൂട്ടറിൽ):',
        'step_dns_record' => 'Type A, name {host}, address {ip}',
        'step_dns_hosts' => 'DNS സെർവർ ഇല്ലെങ്കിൽ, ഓരോ PC-യിലെയും hosts ഫയലിലേക്ക് ഈ വരി ചേർക്കുക (Windows-ൽ {path}, Mac-ൽ {path_mac}):',
        'step_dns_no_ip' => 'ഉണ്ടാക്കേണ്ട കൃത്യമായ റെക്കോർഡ് കാണാൻ മുകളിൽ സെർവർ IP വിലാസം പൂരിപ്പിക്കുക.',
        'step_ca_title' => 'ഓരോ PC-യിലും അതോറിറ്റി സർട്ടിഫിക്കറ്റ് ഇൻസ്റ്റാൾ ചെയ്യുക',
        'step_ca_body' => 'സർട്ടിഫിക്കറ്റിനെ വിശ്വസിക്കാൻ ഇത് PC-കളോട് പറയുന്നു. ഓരോ PC-യിലും ഒരിക്കൽ മാത്രം ചെയ്താൽ മതി, പേരോ IP-യോ മാറ്റിയാൽ മാത്രം വീണ്ടും.',
        'download' => 'ഡൗൺലോഡ്',
        'step_ca_windows' => 'Windows: ഫയലിൽ ഡബിൾ-ക്ലിക്ക് ചെയ്യുക, Install Certificate തിരഞ്ഞെടുക്കുക, Local Machine തിരഞ്ഞെടുക്കുക, തുടർന്ന് Place all certificates in the following store, എന്നിട്ട് Trusted Root Certification Authorities തിരഞ്ഞെടുക്കുക.',
        'step_ca_gpo' => 'ഡൊമെയ്നിലെ ധാരാളം Windows PC-കൾ: Group Policy-യിൽ Computer Configuration → Policies → Windows Settings → Security Settings → Public Key Policies → Trusted Root Certification Authorities എന്നതിന് കീഴിൽ ഫയൽ ഒരിക്കൽ ഇംപോർട്ട് ചെയ്യുക. Intune-ന് ഇത് ഒരു Trusted certificate പ്രൊഫൈലായി പുഷ് ചെയ്യാം.',
        'step_ca_mac' => 'Mac: Keychain Access-ലേക്ക് ചേർക്കാൻ ഫയലിൽ ഡബിൾ-ക്ലിക്ക് ചെയ്യുക, അവിടെ അത് തുറന്ന് When using this certificate എന്നത് Always Trust ആക്കുക.',
        'step_ca_firefox' => 'Windows-ലെ Firefox Windows സർട്ടിഫിക്കറ്റുകൾ സ്വയം ഉപയോഗിക്കും. എന്നിട്ടും മുന്നറിയിപ്പ് വന്നാൽ about:config-ൽ security.enterprise_roots.enabled എന്നത് true ആക്കുക.',
        'step_ca_safe' => 'ഈ അതോറിറ്റിക്ക് {host}-നെ മാത്രമേ സാക്ഷ്യപ്പെടുത്താൻ കഴിയൂ, മറ്റൊന്നിനെയും കഴിയില്ല, അതിനാൽ ഇത് ഇൻസ്റ്റാൾ ചെയ്യുന്നത് മറ്റൊരു വെബ്സൈറ്റിനെയും അനുകരിക്കാൻ അതിനെ അനുവദിക്കുന്നില്ല.',
        'step_restart_title' => 'കണ്ടെയ്നർ റീസ്റ്റാർട്ട് ചെയ്യുക',
        'step_restart_body' => 'നിങ്ങളുടെ docker-compose.yml ഉള്ള ഫോൾഡറിൽ {cmd} പ്രവർത്തിപ്പിക്കുക.',
        'step_restart_done' => 'പൂർത്തിയായി: കണ്ടെയ്നർ ഈ സർട്ടിഫിക്കറ്റ് ഉപയോഗിക്കുന്നു.',
        'step_open_title' => 'FreeITSM HTTPS വഴി തുറക്കുക',
        'step_open_body' => '{url} എന്നതിലേക്ക് പോകുക. ലോഡ് ആകുന്നില്ലെങ്കിൽ, നിങ്ങളുടെ docker-compose.yml പോർട്ട് 443 പ്രസിദ്ധീകരിക്കുന്നുണ്ടോ എന്ന് പരിശോധിക്കുക (സ്റ്റാൻഡേർഡ് ഫയൽ അത് 8443-ലേക്ക് മാപ്പ് ചെയ്യുന്നു). അത് മാറ്റിയിട്ടുണ്ടെങ്കിൽ നിങ്ങളുടെ പോർട്ട് ഉപയോഗിക്കുക.',
