    'modules' => [
        'title' => 'മൊഡ്യൂൾ ആക്സസ്',
        'subtitle' => 'ഹോം സ്ക്രീനിലും നാവിഗേഷനിലും ഓരോ അനലിസ്റ്റിനും ഏതെല്ലാം മൊഡ്യൂളുകൾ കാണാമെന്ന് നിയന്ത്രിക്കുക',
        'info_text' => 'സ്ഥിരസ്ഥിതിയായി എല്ലാ അനലിസ്റ്റുകൾക്കും എല്ലാ മൊഡ്യൂളിലേക്കും ആക്സസ് ഉണ്ട്. ഒരു അനലിസ്റ്റിനെ നിശ്ചിത മൊഡ്യൂളുകളിലേക്ക് പരിമിതപ്പെടുത്താൻ {all_access} ഓഫ് ചെയ്യുക. System മൊഡ്യൂൾ ഡിസേബിൾ ചെയ്യാൻ കഴിയില്ല.',
        'all_access_strong' => 'എല്ലാ ആക്സസും',
