        'col_all_access' => 'എല്ലാ ആക്സസും',
        'load_failed' => 'ഡാറ്റ ലോഡ് ചെയ്യുന്നതിൽ പരാജയപ്പെട്ടു',
        'save_failed' => 'സേവ് ചെയ്യുന്നതിൽ പരാജയപ്പെട്ടു',
    ],
    'calsync' => [
        'title' => 'കലണ്ടർ സിങ്ക്',
        'subtitle' => 'അനലിസ്റ്റുകൾ യഥാർത്ഥത്തിൽ ഉപയോഗിക്കുന്ന കലണ്ടറുകളിലേക്ക് അവരുടെ ഷെഡ്യൂൾ ചെയ്ത ടിക്കറ്റുകൾ ഇടുക, അവർക്ക് ഒരു സബ്സ്ക്രിപ്ഷൻ ലിങ്ക് പ്രസിദ്ധീകരിക്കാമോ എന്ന് തീരുമാനിക്കുക.',
        'needs_db' => 'ആദ്യം ഒരു ഡാറ്റാബേസ് അപ്ഡേറ്റ് ആവശ്യമാണ്',
        'needs_db_desc' => 'System → Database Verification പ്രവർത്തിപ്പിക്കുക, എന്നിട്ട് ഈ പേജിലേക്ക് തിരികെ വരിക.',
        'conn_heading' => 'കണക്ഷൻ',
        'conns_heading' => 'കണക്ഷനുകൾ',
        'conns_desc' => 'അനലിസ്റ്റുകളുടെ സ്വന്തം കലണ്ടറുകളിലേക്ക് FreeITSM എങ്ങനെ ഇവന്റുകൾ എഴുതുന്നു എന്ന്. ആവശ്യമുള്ളത്ര ചേർക്കുക - Microsoft 365, ഒന്നോ അതിലധികമോ CalDAV സെർവറുകൾ, അല്ലെങ്കിൽ രണ്ടും. തങ്ങളുടെ ജോലി ഏതിലേക്ക് പോകണമെന്ന് ഓരോ അനലിസ്റ്റും <strong>Preferences &rarr; My work calendar</strong> എന്നതിന് കീഴിൽ തിരഞ്ഞെടുക്കുന്നു.',
        'conns_none' => 'ഇതുവരെ കണക്ഷനുകളില്ല. ഒന്നില്ലെങ്കിലും സബ്സ്ക്രിപ്ഷൻ ലിങ്കുകൾ പ്രവർത്തിക്കും.',
        'conn_add' => 'ചേർക്കുക',
        'conn_edit' => 'എഡിറ്റ് ചെയ്യുക',
        'conn_new' => 'പുതിയ കണക്ഷൻ',
        'conn_editing' => '“{name}” എഡിറ്റ് ചെയ്യുക',
        'conn_users' => '{n} അനലിസ്റ്റ് ഇത് ഉപയോഗിക്കുന്നു',
        'conn_borrowed' => 'ഒരു മെയിൽബോക്സിൽ നിന്ന് ആപ്പ് രജിസ്ട്രേഷൻ കടം വാങ്ങുന്നു',
        'conn_own' => 'അതിന്റേതായ ആപ്പ് രജിസ്ട്രേഷൻ',
        'conn_failing' => 'പരാജയപ്പെടുന്നു',
        'col_connection' => 'കണക്ഷൻ',
        'col_calendar' => 'കലണ്ടർ',
        'not_chosen' => 'ഇതുവരെ തിരഞ്ഞെടുത്തിട്ടില്ല',
        'provider_label' => 'കലണ്ടർ സിസ്റ്റം',
        'provider_microsoft' => 'Microsoft 365 / Exchange',
        'provider_caldav_short' => 'CalDAV',
        'provider_caldav' => 'ഒരു CalDAV സെർവർ (Nextcloud, Baïkal, Radicale, iCloud, Fastmail…)',
        'caldav_desc' => 'ഓരോ അനലിസ്റ്റിന്റെയും ഷെഡ്യൂൾ ചെയ്ത ജോലി, <strong>ആ അനലിസ്റ്റായി സൈൻ ഇൻ ചെയ്ത്</strong>, നിങ്ങളുടെ CalDAV സെർവറിലെ ഒരു കലണ്ടറിലേക്ക് FreeITSM എഴുതുന്നു. ഒരു അക്കൗണ്ടിന് എല്ലാവരുടെയും കലണ്ടറിലേക്ക് എഴുതാൻ ഒരു CalDAV സെർവറിന് വഴിയില്ല, അതിനാൽ ഇവിടെ പാസ്‌വേഡ് ഇല്ല: ഓരോ അനലിസ്റ്റും <strong>Preferences &rarr; My work calendar</strong> എന്നതിന് കീഴിൽ സൈൻ ഇൻ ചെയ്ത് അവരുടെ കലണ്ടർ തിരഞ്ഞെടുക്കുന്നു.',
        'server_url' => 'സെർവർ വിലാസം',
        'server_url_hint' => 'സെർവറിന്റെ DAV വിലാസം, അതിന്റെ വെബ് പേജ് അല്ല. Baïkal: <code>https://server/dav.php/</code> &middot; Nextcloud: <code>https://server/remote.php/dav/</code> &middot; Radicale: <code>https://server/</code>. ഈ സെർവറിലെ കലണ്ടറുകൾ മാത്രമേ അനലിസ്റ്റുകൾക്ക് തിരഞ്ഞെടുക്കാൻ കഴിയൂ.',
        'caldav_auth' => 'സൈൻ-ഇൻ രീതി',
        'auth_auto' => 'ഓട്ടോമാറ്റിക് (ശുപാർശ ചെയ്യുന്നത്)',
        'auth_digest' => 'Digest',
        'auth_basic' => 'Basic',
        'caldav_auth_hint' => 'കാരണമില്ലെങ്കിൽ ഇത് ഓട്ടോമാറ്റിക് ആയി തന്നെ വിടുക. ഒരു സ്റ്റാൻഡേർഡ് Baïkal-ന് Basic-ന് പകരം Digest വേണം, ഓട്ടോമാറ്റിക് സെർവർ ഏതാണ് നൽകുന്നതെന്ന് ചോദിക്കും.',
        'caldav_probe' => 'ഒരു സൈൻ-ഇൻ പരീക്ഷിക്കുക (ഓപ്ഷണൽ, ഈ ടെസ്റ്റിന് മാത്രം ഉപയോഗിക്കും, സേവ് ചെയ്യില്ല)',
        'probe_user' => 'ഉപയോക്തൃനാമം',
        'probe_pass' => 'പാസ്‌വേഡ്',
        'caldav_test_ok' => 'കണക്റ്റ് ചെയ്തു. ആ വിലാസം ഒരു കലണ്ടർ സെർവറാണ്.',
        'caldav_test_failed_hint' => 'വിലാസം സെർവറിന്റെ വെബ് പേജ് അല്ല, DAV പാത്ത് ആണെന്ന് ഉറപ്പാക്കുക, നെറ്റ്‌വർക്ക് വഴി FreeITSM-ന് അതിലേക്ക് എത്താൻ കഴിയുമെന്നും.',
        'caldav_probe_ok' => '{user} സൈൻ ഇൻ ചെയ്തു, ഇവയിലേക്ക് എഴുതാൻ കഴിയും: {list}.',
        'caldav_probe_none' => '{user} സൈൻ ഇൻ ചെയ്തു, പക്ഷേ ഇവന്റുകൾ വെക്കാൻ കഴിയുന്ന ഒരു കലണ്ടറും ഇല്ല.',
        'caldav_probe_bad' => '{user} ആയി സൈൻ ഇൻ ചെയ്യാൻ കഴിഞ്ഞില്ല: {error}',
        'caldav_probe_auth' => 'സെർവർ {auth} ഓതന്റിക്കേഷൻ നൽകി.',
        'caldav_no_notify' => 'CalDAV സെർവറുകൾ മാറ്റ അറിയിപ്പുകൾ അയക്കില്ല, അതിനാൽ ഒരു കലണ്ടറിൽ വരുത്തിയ മാറ്റങ്ങൾ ഷെഡ്യൂൾ ചെയ്ത ജോലി പ്രവർത്തിക്കുമ്പോൾ എത്തും.',
        'people_desc_caldav' => 'ഓരോ അനലിസ്റ്റും CalDAV സെർവറിലേക്ക് സൈൻ ഇൻ ചെയ്ത് Preferences-ന് കീഴിൽ സ്വന്തം കലണ്ടർ തിരഞ്ഞെടുക്കുന്നു. ഒരു അഡ്മിനിസ്ട്രേറ്റർക്ക് അവർക്കുവേണ്ടി ഇത് തിരഞ്ഞെടുക്കാൻ കഴിയില്ല, കാരണം അതിലേക്ക് എത്തുന്ന പാസ്‌വേഡ് അനലിസ്റ്റിന് മാത്രമേ ഉള്ളൂ.',
        'no_account' => 'സൈൻ ഇൻ ചെയ്തിട്ടില്ല',
        'switch_title' => 'ഈ കണക്ഷൻ എഴുതുന്ന സ്ഥലം മാറ്റണോ?',
        'switch_confirm' => 'ഈ കണക്ഷൻ അനലിസ്റ്റുകളുടെ കലണ്ടറുകളിൽ ഇട്ട {mapped} ഇവന്റ്(കൾ) ഇത് തിരികെയെടുക്കും, ഇത് ഉപയോഗിക്കുന്ന {pushing} അനലിസ്റ്റ്(കൾ)ക്ക് കലണ്ടർ സിങ്ക് ഓഫ് ചെയ്യും, അതുവഴി ഓരോരുത്തർക്കും വീണ്ടും സെറ്റപ്പ് ചെയ്യാം. മറ്റ് കണക്ഷനുകളിലെ അനലിസ്റ്റുകളെയും സബ്സ്ക്രിപ്ഷൻ ലിങ്കുകളെയും ഇത് ബാധിക്കില്ല.',
        'switch_ok' => 'മാറ്റുക',
        'switch_done' => 'സംരക്ഷിച്ചു. ഈ കണക്ഷനിലെ അനലിസ്റ്റുകൾക്കുള്ള കലണ്ടർ സിങ്ക് റീസെറ്റ് ചെയ്തു.',
        'perm_title' => 'ഇത് പ്രവർത്തിക്കുന്നതിന് മുമ്പ്',
        'perm_body' => 'ആപ്പ് രജിസ്ട്രേഷന് <strong>Application</strong> പെർമിഷനായി <strong>Calendars.ReadWrite</strong> വേണം (Delegated അല്ല — Azure-ൽ അവ വെവ്വേറെ ലിസ്റ്റുകളാണ്), അഡ്മിൻ കൺസെന്റ് നൽകിയിരിക്കണം. ഈ പെർമിഷൻ <strong>ടെനന്റിലെ എല്ലാ മെയിൽബോക്സിലേക്കും</strong> എഴുതാൻ FreeITSM-നെ അനുവദിക്കുന്നു എന്നത് ശ്രദ്ധിക്കുക. നിങ്ങൾ നൽകാൻ ഉദ്ദേശിക്കുന്നതിലും കൂടുതലാണ് ഇതെങ്കിൽ, Exchange Online-ലെ ഒരു Application Access Policy ഉപയോഗിച്ച് നിങ്ങളുടെ അനലിസ്റ്റുകളുടെ മെയിൽ-എനേബിൾഡ് സെക്യൂരിറ്റി ഗ്രൂപ്പിലേക്ക് ആപ്പിനെ സ്കോപ്പ് ചെയ്യുക.',
        'name' => 'പേര്',
        'source_mailbox' => 'ഒരു മെയിൽബോക്സിൽ നിന്ന് ക്രെഡൻഷ്യലുകൾ കടം വാങ്ങുക',
        'source_own' => 'ക്രെഡൻഷ്യലുകൾ നൽകുക',
        'mailbox' => 'മെയിൽബോക്സ്',
        'no_mailboxes' => 'ഈ സിസ്റ്റത്തിലെ ഒരു Microsoft മെയിൽബോക്സിനും കടം വാങ്ങാൻ Azure ക്രെഡൻഷ്യലുകൾ ഇല്ല, അതിനാൽ താഴെ അവ നൽകുക. നിങ്ങളുടെ അനലിസ്റ്റുകളുടെ കലണ്ടറുകൾ ഇൻടേക്ക് മെയിൽബോക്സുകളിൽ നിന്ന് വ്യത്യസ്തമായ ഒരു ടെനന്റിലാണെങ്കിൽ, അല്ലെങ്കിൽ നിങ്ങളുടെ ഇൻടേക്ക് Microsoft അല്ലെങ്കിൽ, ഇത് സാധാരണമാണ്.',
        'tenant_id' => 'ഡയറക്ടറി (ടെനന്റ്) ID',
        'client_id' => 'ആപ്ലിക്കേഷൻ (ക്ലയന്റ്) ID',
        'client_secret' => 'ക്ലയന്റ് സീക്രട്ട്',
        'secret_note' => 'സീക്രട്ട് എൻക്രിപ്റ്റ് ചെയ്ത് സൂക്ഷിക്കും, വീണ്ടും കാണിക്കില്ല. ഇതിനകം സൂക്ഷിച്ചത് നിലനിർത്താൻ എഡിറ്റ് ചെയ്യുമ്പോൾ ശൂന്യമായി വിടുക.',
        'test' => 'പരിശോധിക്കുക',
        'testing' => 'പരിശോധിക്കുന്നു…',
        'probe' => 'ഈ മെയിൽബോക്സിലേക്ക് എത്താൻ കഴിയുമോ എന്നും പരിശോധിക്കുക (ഓപ്ഷണൽ)',
        'saved' => 'സംരക്ഷിച്ചു',
        'last_error' => 'അവസാന ശ്രമം ഈ പിശകോടെ പരാജയപ്പെട്ടു:',
        'test_ok' => 'കണക്റ്റ് ചെയ്തു. ക്രെഡൻഷ്യലുകൾ പ്രവർത്തിക്കുന്നു, പെർമിഷൻ നൽകിയിട്ടുണ്ട്.',
        'test_borrowed' => '“{name}” എന്ന മെയിൽബോക്സിൽ നിന്നുള്ള ആപ്പ് രജിസ്ട്രേഷൻ ഉപയോഗിക്കുന്നു.',
        'test_failed' => 'കണക്റ്റ് ചെയ്യാൻ കഴിഞ്ഞില്ല.',
        'test_failed_hint' => 'ക്ലയന്റ് സീക്രട്ട് കാലഹരണപ്പെട്ടിട്ടില്ലെന്നും, Application permissions-ന് കീഴിൽ Calendars.ReadWrite അഡ്മിൻ കൺസെന്റോടെ ലിസ്റ്റ് ചെയ്തിട്ടുണ്ടെന്നും ഉറപ്പാക്കുക.',
        'probe_ok' => '{addr}-ന് FreeITSM-ന് എഴുതാൻ കഴിയുന്ന ഒരു കലണ്ടർ ഉണ്ട്.',
        'probe_bad' => '{addr}-ന് ഒരു കലണ്ടറും കണ്ടെത്തിയില്ല. ഈ ടെനന്റിലെ യഥാർത്ഥ മെയിൽബോക്സ് ആണ് ആ വിലാസം എന്ന് ഉറപ്പാക്കുക — ഒരു അനലിസ്റ്റിന്റെ FreeITSM ഇമെയിൽ വിലാസം എപ്പോഴും അവരുടെ മെയിൽബോക്സ് വിലാസമായിരിക്കില്ല.',
        'conn_delete_confirm' => '“{name}” ഇല്ലാതാക്കണോ?',
        'conn_delete_title' => 'ഈ കണക്ഷൻ ഇല്ലാതാക്കണോ?',
        'conn_delete_used' => 'ഈ കണക്ഷൻ അനലിസ്റ്റുകളുടെ കലണ്ടറുകളിൽ ഇട്ട {mapped} ഇവന്റ്(കൾ) FreeITSM തിരികെയെടുക്കും, ഇത് ഉപയോഗിക്കുന്ന {pushing} അനലിസ്റ്റ്(കൾ)ക്ക് കലണ്ടർ സിങ്ക് ഓഫ് ചെയ്യും. മറ്റ് കണക്ഷനുകളിലെ അനലിസ്റ്റുകളെ ഇത് ബാധിക്കില്ല.',
        'conn_deleted' => 'കണക്ഷൻ ഇല്ലാതാക്കി',
        'people_heading' => 'ഓരോ അനലിസ്റ്റും ഏത് മെയിൽബോക്സിലേക്ക് സിങ്ക് ചെയ്യുന്നു',
        'people_desc' => 'സ്ഥിരസ്ഥിതിയായി FreeITSM അനലിസ്റ്റിന്റെ അക്കൗണ്ടിലെ ഇമെയിൽ വിലാസം ഉപയോഗിക്കുന്നു, ഇത് പലപ്പോഴും അവരുടെ മെയിൽബോക്സ് ആയിരിക്കില്ല &mdash; ഒരു ലോക്കൽ അക്കൗണ്ട്, അല്ലെങ്കിൽ മറ്റെന്തെങ്കിലും അടിസ്ഥാനമാക്കിയുള്ള ഒരു ഡയറക്ടറി ഇംപോർട്ട്. ഇവിടെ ഇത് ഓവർറൈഡ് ചെയ്യുക. തങ്ങളുടെ ജോലി സിങ്ക് ചെയ്യണോ <em>എന്നത്</em> അനലിസ്റ്റുകൾ തിരഞ്ഞെടുക്കുന്നു; അത് <em>എവിടേക്ക്</em> പോകുന്നു എന്നത് ഒരു അഡ്മിനിസ്ട്രേറ്റർ മാത്രം തിരഞ്ഞെടുക്കുന്നു.',
        'col_analyst' => 'അനലിസ്റ്റ്',
        'col_status' => 'അനലിസ്റ്റ് തിരഞ്ഞെടുത്തത്',
        'check_save' => 'പരിശോധിച്ച് സംരക്ഷിക്കുക',
        'mode_off' => 'ഓഫ്',
        'mode_push' => 'സിങ്ക് ചെയ്യുന്നു',
        'mode_feed' => 'സബ്സ്ക്രൈബ് ചെയ്തു',
        'mode_error' => 'അവസാന സിങ്ക് പരാജയപ്പെട്ടു',
        'tasks_work' => 'ടാസ്കുകൾ: ആസൂത്രണം ചെയ്തത്',
        'tasks_due' => 'ടാസ്കുകൾ: അവസാന തീയതികൾ',
        'tasks_both' => 'ടാസ്കുകൾ: രണ്ടും',
        'tasks_note' => 'ഈ അനലിസ്റ്റ് അവരുടെ ടാസ്കുകൾ ഉൾപ്പെടുത്താൻ തിരഞ്ഞെടുത്തിട്ടുണ്ട്. ഇത് അവർ തന്നെ Preferences-ന് കീഴിൽ തിരഞ്ഞെടുക്കുന്നു; ഇവിടെ അവർക്കുവേണ്ടി ഇത് സെറ്റ് ചെയ്യാൻ കഴിയില്ല.',
        'saved_unverified' => 'സംരക്ഷിച്ചു. കണക്ഷൻ പ്രവർത്തിക്കാത്തതിനാൽ വിലാസം പരിശോധിക്കാൻ കഴിഞ്ഞില്ല — മുകളിൽ ഇത് ടെസ്റ്റ് ചെയ്യുക.',
        'inbound_heading' => 'കലണ്ടറിൽ വരുത്തിയ മാറ്റങ്ങൾ',
        'inbound_desc' => 'Outlook-ൽ ഇത്തരം ഒരു അപ്പോയിന്റ്മെന്റ് മാറ്റുക, ടിക്കറ്റ് അതിനെ പിന്തുടരും. ഇതിന് <code>cron/calendar_sync_pull.php</code> ജോലി പ്രവർത്തിക്കണം &mdash; ഓരോ 5 മിനിറ്റിലും യുക്തിസഹമാണ്. ഇതില്ലാതെ സിങ്ക് ഒരു ദിശയിൽ മാത്രമായിരിക്കും, ഇന്ന് ഇത് കൃത്യമായി അങ്ങനെയാണ് പ്രവർത്തിക്കുന്നത്.',
        'accept_deletes' => 'അപ്പോയിന്റ്മെന്റ് ഇല്ലാതാക്കുന്നത് ടിക്കറ്റിന്റെ ഷെഡ്യൂൾ ഒഴിവാക്കും',
        'notify_url' => 'അറിയിപ്പ് URL (ഓപ്ഷണൽ)',
        'notify_url_note' => 'ഷെഡ്യൂൾ ചെയ്ത ചെക്കിനെ മാത്രം ആശ്രയിക്കാൻ ശൂന്യമായി വിടുക, ഇത് നല്ലതു തന്നെയാണ് &mdash; മാറ്റങ്ങൾ അപ്പോൾ ഏതാനും മിനിറ്റുകൾക്കുള്ളിൽ എത്തും. ഇത് പൂരിപ്പിച്ചാൽ, എന്തെങ്കിലും മാറുന്ന നിമിഷം Microsoft FreeITSM-നെ അറിയിക്കും, അത് സെക്കൻഡുകൾക്കുള്ളിൽ എത്തും. ഇത് <code>/api/calendar/graph_notify.php</code> എന്ന് അവസാനിക്കുന്ന, <strong>ഇന്റർനെറ്റിൽ നിന്ന് Microsoft-ന് എത്താൻ കഴിയുന്ന ഒരു HTTPS വിലാസം</strong> ആയിരിക്കണം. ഏത് വിധേനയും ഷെഡ്യൂൾ ചെയ്ത ജോലി ഇപ്പോഴും ആവശ്യമാണ്: ഇത് സബ്സ്ക്രിപ്ഷനുകൾ പുതുക്കുന്നു, നഷ്ടമായേക്കാവുന്ന ഏതെങ്കിലും അറിയിപ്പിനെ ഇത് പിടിക്കുകയും ചെയ്യുന്നു.',
        'notify_suggest' => 'ഈ വിലാസം ഉപയോഗിക്കുക',
        'notify_suggest_note' => 'നിങ്ങൾ ഇപ്പോൾ ഉപയോഗിക്കുന്ന വിലാസത്തിൽ നിന്ന് പൂരിപ്പിച്ചത്. പുറത്തുനിന്ന് ഇതിലേക്ക് എത്താൻ കഴിയുമെന്ന് ഉറപ്പാക്കുക — ഒരു പ്രോക്സിക്കോ ടണലിനോ പിന്നിൽ പലപ്പോഴും ഇത് സാധ്യമല്ല, തെറ്റായ ഒന്ന് വിലാസത്തെക്കുറിച്ചല്ല, വാലിഡേഷനെക്കുറിച്ചുള്ള ഒരു സന്ദേശത്തോടെ പരാജയപ്പെടും.',
        'notify_saved' => 'അടുത്ത തവണ പ്രവർത്തിക്കുമ്പോൾ ഷെഡ്യൂൾ ചെയ്ത ജോലി സബ്സ്ക്രിപ്ഷനുകൾ സൃഷ്ടിക്കുകയോ അപ്ഡേറ്റ് ചെയ്യുകയോ ചെയ്യും.',
        'notify_active' => '{n} സബ്സ്ക്രിപ്ഷൻ സജീവമാണ്',
        'health_checked' => 'കലണ്ടറുകൾ അവസാനമായി പരിശോധിച്ചത് {n} മുമ്പ്.',
        'health_never' => 'കലണ്ടറുകൾ ഒരിക്കലും പരിശോധിച്ചിട്ടില്ല.',
        'health_stale_note' => 'Outlook-ൽ വരുത്തിയ മാറ്റങ്ങൾ ഷെഡ്യൂൾ ചെയ്ത ജോലി പ്രവർത്തിക്കുമ്പോൾ എത്തും, അതിനാൽ സാധാരണയായി ഇതിനർത്ഥം അത് നിലച്ചു എന്നാണ് &mdash; <code>cron/calendar_sync_pull.php</code> ഇപ്പോഴും അതിന്റെ ഷെഡ്യൂളിൽ പ്രവർത്തിക്കുന്നുണ്ടെന്ന് പരിശോധിക്കുക. സബ്സ്ക്രിപ്ഷനുകൾ പുതുക്കുന്നതും ഇതുതന്നെയാണ്, അതിനാൽ ഇത് നിലച്ച് കുറച്ച് ദിവസങ്ങൾക്കുള്ളിൽ അറിയിപ്പുകൾ നിലയ്ക്കും. അര മണിക്കൂറിൽ ഒരിക്കലിലും കുറച്ച് തവണ ബോധപൂർവ്വം ഇത് പ്രവർത്തിപ്പിക്കുകയാണെങ്കിൽ, ഇത് പ്രതീക്ഷിക്കാവുന്നതാണ്.',
        'health_subs' => 'അറിയിപ്പുകൾ: {total}-ൽ {n} സബ്സ്ക്രൈബ് ചെയ്തു.',
        'health_just_now' => 'ഒരു മിനിറ്റിൽ താഴെ',
        'health_mins' => '{n} മിനിറ്റ്',
        'health_hours' => '{n} മണിക്കൂർ',
        'health_days' => '{n} ദിവസം',
        'sub_ok' => 'അറിയിപ്പ് നൽകി',
        'sub_expires' => 'സബ്സ്ക്രിപ്ഷൻ {n}-നുള്ളിൽ പുതുക്കും',
        'sub_none' => 'സബ്സ്ക്രൈബ് ചെയ്തിട്ടില്ല',
        'sub_none_note' => 'ഒരു അറിയിപ്പ് വിലാസം സെറ്റ് ചെയ്തിട്ടുണ്ട്, പക്ഷേ ഈ വ്യക്തിക്ക് വിളിക്കാൻ Microsoft-ന് ഒന്നുമില്ല, അതിനാൽ ഷെഡ്യൂൾ ചെയ്ത ജോലി പ്രവർത്തിക്കുമ്പോൾ മാത്രമേ അവരുടെ മാറ്റങ്ങൾ എത്തൂ. അടുത്ത റൺ ഇത് സൃഷ്ടിക്കാൻ ശ്രമിക്കും; തുടർച്ചയായി പരാജയപ്പെട്ടാൽ കാരണം ഇവിടെ കാണിക്കും.',
        'sub_lapsed' => 'സബ്സ്ക്രിപ്ഷൻ കാലഹരണപ്പെട്ടു',
        'accept_deletes_note' => 'സ്ഥിരസ്ഥിതിയായി ഓഫാണ്. ഇത് ഓണാക്കിയാൽ, ഫോണിൽ ഇത്തരം ഒന്ന് ഇല്ലാതാക്കുന്ന ഒരു അനലിസ്റ്റ് ഇരിക്കുമ്പോൾ ടിക്കറ്റ് ഇതിനകം അൺഷെഡ്യൂൾ ആയതായി കാണും &mdash; ഇതാണ് പലപ്പോഴും ലക്ഷ്യം. ഇത്തരം ഓരോ മാറ്റവും ടിക്കറ്റിന്റെ ചരിത്രത്തിൽ എഴുതും, ഒറ്റയടിക്ക് അസാധാരണമാം വിധം വലിയ എണ്ണം ഇല്ലാതാക്കലുകൾ അനുസരിക്കുന്നതിന് പകരം നിരസിക്കും, കാരണം ഇത് ഒരു നിർദ്ദേശത്തേക്കാൾ ഒരു തകരാറാകാനാണ് സാധ്യത. ഇത് ഓഫായിരിക്കുമ്പോൾ, ഇല്ലാതാക്കിയ ഒരു അപ്പോയിന്റ്മെന്റ് ടിക്കറ്റ് അടുത്തതായി മാറുമ്പോൾ വെറുതെ വീണ്ടും പ്രത്യക്ഷപ്പെടും.',
        'feed_heading' => 'സബ്സ്ക്രിപ്ഷൻ ലിങ്കുകൾ',
        'feed_desc' => 'അനലിസ്റ്റുകൾക്ക് അവരുടെ ഷെഡ്യൂൾ ചെയ്ത ജോലി ഒരു കലണ്ടർ സബ്സ്ക്രിപ്ഷൻ ലിങ്കായി പ്രസിദ്ധീകരിക്കാം, ഇത് ഏത് കലണ്ടർ ആപ്പിലും പ്രവർത്തിക്കും. ഒരു ലിങ്ക് ഒരു ലോഗിൻ അല്ല, ഒരു രഹസ്യ URL ആണ്, അതിനാൽ അത് കൈവശമുള്ള ആർക്കും അത് കാണിക്കുന്നത് വായിക്കാം.',
        'feed_label' => 'സബ്സ്ക്രിപ്ഷൻ ലിങ്കുകൾ അനുവദിക്കുക',
        'feed_full' => 'അതെ — ടിക്കറ്റ് വിഷയങ്ങൾ ഉൾപ്പെടെ',
        'feed_ref' => 'അതെ — പക്ഷേ ടിക്കറ്റ് നമ്പറുകൾ മാത്രം, വിഷയങ്ങളില്ല',
        'feed_off' => 'ഇല്ല',
        'feed_note' => 'അനലിസ്റ്റുകൾക്ക് എപ്പോഴും ഇതിലും കുറച്ച് പ്രസിദ്ധീകരിക്കാൻ തിരഞ്ഞെടുക്കാം, ഒരിക്കലും കൂടുതൽ അല്ല. ഇത് ഓഫ് ചെയ്യുന്നത് ഇതിനകം നൽകിയ ലിങ്കുകൾ ഉടനടി നിർത്തും.',
