    'preferences' => [
        'title' => 'മുൻഗണനകൾ',
        'subtitle' => 'നിങ്ങളുടെ അക്കൗണ്ടിൽ സേവ് ചെയ്ത വ്യക്തിഗത ക്രമീകരണങ്ങൾ — ബ്രൗസറുകൾക്കിടയിൽ അവ നിങ്ങളെ പിന്തുടരും.',
        'tab_general' => 'പൊതുവായത്',
