        'tab_display' => 'ഡിസ്പ്ലേ',
        'tab_details' => 'എന്റെ വിശദാംശങ്ങൾ',
        'language_heading' => 'ഇന്റർഫേസ് ഭാഷ',
        'language_desc' => 'FreeITSM UI-യിലുടനീളം ഉപയോഗിക്കുന്ന ഭാഷ. നിങ്ങൾ തിരഞ്ഞെടുത്ത ഭാഷയിൽ ഇതുവരെ ലഭ്യമല്ലാത്ത സ്ട്രിംഗുകൾക്ക് ഇംഗ്ലീഷിലേക്ക് മടങ്ങും. മാറ്റുമ്പോൾ പേജ് വീണ്ടും ലോഡ് ചെയ്യും.',
        'saving' => 'സേവ് ചെയ്യുന്നു…',
        'notif_heading' => 'ബെല്ലിൽ',
        'notif_desc' => 'സ്ക്രീനിന്റെ മുകളിലുള്ള ബെല്ലിൽ ഇവയിൽ ഏതൊക്കെ എന്തെങ്കിലും ഇടും. നിങ്ങളുടെ സ്വന്തം പ്രവർത്തനങ്ങളെക്കുറിച്ച് നിങ്ങളെ ഒരിക്കലും അറിയിക്കില്ല, ഒരേ ടിക്കറ്റിലെ പല മാറ്റങ്ങളും ഒന്നായി ഗ്രൂപ്പ് ചെയ്യും.',
        'sound_heading' => 'അറിയിപ്പ് ശബ്ദം',
        'sound_desc' => 'ബെല്ലിൽ പുതിയതെന്തെങ്കിലും വരുമ്പോൾ, അല്ലെങ്കിൽ War Room-ൽ ആരെങ്കിലും നിങ്ങളെ mention ചെയ്യുമ്പോൾ ഒരു ചെറിയ ശബ്ദം പ്ലേ ചെയ്യുക. നിങ്ങൾ ഒരു ശബ്ദം തിരഞ്ഞെടുക്കാത്തിടത്തോളം ഓഫ് ആയിരിക്കും.',
        'sound_off' => 'ശബ്ദമില്ല',
        'sound_chime' => 'Chime',
        'sound_ping' => 'Ping',
        'sound_knock' => 'Knock',
        'sound_play' => 'പ്ലേ ചെയ്യുക',
        'sound_note' => 'പേജിൽ എവിടെയെങ്കിലും ക്ലിക്ക് ചെയ്യുന്നത് വരെ നിങ്ങളുടെ ബ്രൗസർ ഒരു ശബ്ദവും പ്ലേ ചെയ്യില്ല, അതിനാൽ ഒരു ടാബ് തുറന്നതിന് ശേഷമുള്ള ആദ്യ അറിയിപ്പ് നിശബ്ദമായേക്കാം. നിങ്ങൾ ടാബ് തുറന്നപ്പോൾ ഇതിനകം കാത്തിരുന്ന അറിയിപ്പുകൾക്ക് ഒന്നും കേൾക്കില്ല.',
        'cal_subtasks_heading' => 'ടാസ്ക് കലണ്ടറിൽ ഉപടാസ്കുകൾ',
        'cal_subtasks_desc' => 'കലണ്ടർ ടാസ്കുകൾക്കൊപ്പം ഉപടാസ്കുകളും കാണിക്കുമോ എന്ന്. കലണ്ടറിന്റെ സൈഡ്ബാറിൽ ഇതേ നിയന്ത്രണം ഉണ്ട്, ഇവ രണ്ടും ഒരേപോലെ നിലനിൽക്കും.',
        'task_view_heading' => 'ഒരു ടാസ്ക് തുറക്കുമ്പോൾ',
        'task_view_desc' => 'ഒരു ടാസ്ക് ബോർഡിന്റെ വശത്തുള്ള പാനലിലാണോ, അതോ വിവരണത്തിനും അഭിപ്രായങ്ങൾക്കും ഇടമുള്ള ഒരു വലിയ വിൻഡോയിലാണോ തുറക്കുന്നത്.',
        'task_view_panel' => 'സൈഡ് പാനലിൽ',
        'task_view_modal' => 'ഒരു വലിയ വിൻഡോയിൽ',
        'desktop_heading' => 'ഡെസ്ക്ടോപ്പ് അറിയിപ്പുകൾ',
        'desktop_desc' => 'ബെല്ലിൽ നിന്നുള്ള ഓരോ പുതിയ അറിയിപ്പും നിങ്ങളുടെ കമ്പ്യൂട്ടറിൽ ഒരു അറിയിപ്പായി കാണിക്കുക - Windows-ലെ Edge-ൽ ഒരു Windows അറിയിപ്പ് - അങ്ങനെ മറ്റൊരു വിൻഡോയിൽ ജോലി ചെയ്യുമ്പോഴും നിങ്ങൾ അത് കാണും. ഇവ എത്താൻ FreeITSM ഒരു ബ്രൗസർ ടാബിൽ തുറന്നിരിക്കണം.',
        'desktop_label' => 'ഡെസ്ക്ടോപ്പ് അറിയിപ്പുകൾ കാണിക്കുക',
        'desktop_test' => 'പരിശോധിക്കുക',
        'desktop_test_title' => 'ഡെസ്ക്ടോപ്പ് അറിയിപ്പുകൾ ഓണാണ്',
        'desktop_test_body' => 'ബെല്ലിൽ നിന്നുള്ള പുതിയ അറിയിപ്പുകൾ ഇതുപോലെ കാണും.',
        'desktop_ask' => 'ഇത് ഓണാക്കുമ്പോൾ, ഈ സൈറ്റിൽ നിന്നുള്ള അറിയിപ്പുകൾ അനുവദിക്കണോ എന്ന് നിങ്ങളുടെ ബ്രൗസർ ചോദിക്കും.',
        'desktop_allowed' => 'ഈ സൈറ്റിൽ നിന്നുള്ള അറിയിപ്പുകൾ നിങ്ങളുടെ ബ്രൗസർ അനുവദിക്കുന്നു.',
        'desktop_blocked' => 'ഈ സൈറ്റിൽ നിന്നുള്ള അറിയിപ്പുകൾ നിങ്ങളുടെ ബ്രൗസർ തടയുന്നു. ബ്രൗസറിന്റെ സൈറ്റ് ക്രമീകരണങ്ങളിൽ (വിലാസത്തിന് അരികിലെ പാഡ്ലോക്ക്) അവ അനുവദിക്കുക, എന്നിട്ട് ഇത് ഓണാക്കുക.',
        'desktop_unsupported' => 'ഈ ബ്രൗസറിന് ഡെസ്ക്ടോപ്പ് അറിയിപ്പുകൾ കാണിക്കാനാവില്ല.',
        'desktop_insecure' => 'https വഴി തുറന്ന സൈറ്റിൽ മാത്രമേ ബ്രൗസറുകൾ ഡെസ്ക്ടോപ്പ് അറിയിപ്പുകൾ അനുവദിക്കൂ.',
        'task_email_heading' => 'നിങ്ങൾക്ക് നൽകിയ ടാസ്കുകൾ',
        'task_email_desc' => 'ഒരു ടാസ്ക് നിങ്ങൾക്ക് നൽകുമ്പോഴെല്ലാം - നിങ്ങൾക്കായി ഒന്ന് സൃഷ്ടിക്കുമ്പോഴോ മറ്റൊരാളിൽ നിന്ന് നിങ്ങൾക്ക് കൈമാറുമ്പോഴോ - ഒരു ഇമെയിൽ ലഭിക്കും. നിങ്ങൾ സ്വയം നൽകുന്ന ടാസ്കിന് ഒന്നും അയയ്ക്കില്ല.',
        'task_email_label' => 'ഒരു ടാസ്ക് എനിക്ക് നൽകുമ്പോൾ എന്നെ ഇമെയിൽ ചെയ്യുക',
        'board_subtasks_heading' => 'ടാസ്ക് ബോർഡിലെ ഉപടാസ്കുകൾ',
        'board_subtasks_desc' => 'ഉപടാസ്കുകളുള്ള ഒരു ടാസ്ക് ബോർഡിലെ അതിന്റെ കാർഡിന് താഴെ അവയെ പട്ടികപ്പെടുത്തുന്നു. ഏതൊക്കെ എന്ന് തിരഞ്ഞെടുക്കുക - കാർഡ് എപ്പോഴും എണ്ണം കാണിക്കും, എണ്ണത്തിൽ ക്ലിക്ക് ചെയ്താൽ ആ കാർഡിന്റെ ലിസ്റ്റ് കാണിക്കുകയോ മറയ്ക്കുകയോ ചെയ്യും. ഇതേ തിരഞ്ഞെടുപ്പ് Tasks സൈഡ്ബാറിലും ഉണ്ട്.',
        'board_subtasks_label' => 'എല്ലാം പൂർത്തിയായാൽ അവ മറയ്ക്കുക',
        'board_subtasks_all' => 'എല്ലാ ഉപടാസ്കുകളും',
        'board_subtasks_open' => 'ചെയ്യാൻ ബാക്കിയുള്ളവ മാത്രം',
        'board_subtasks_none' => 'ഒന്നുമില്ല - എണ്ണം മാത്രം',
        'search_dismiss_heading' => 'സെർച്ച് പാനൽ അടയ്ക്കൽ',
        'search_dismiss_desc' => 'സെർച്ച് പാനൽ വഴിയിൽ നിന്ന് വലിച്ച് മാറ്റി തുറന്ന് വിടാം, അതിനാൽ സ്ഥിരസ്ഥിതിയായി അതിന്റെ ✕ അല്ലെങ്കിൽ Escape കീ മാത്രമേ ഇത് അടയ്ക്കൂ. ഫോൾഡർ ലിസ്റ്റ്, ടിക്കറ്റ് ലിസ്റ്റ് അല്ലെങ്കിൽ ടൂൾബാർ എന്നിവയിൽ ക്ലിക്ക് ചെയ്താലുടൻ ഇത് അടയ്ക്കാൻ ഇത് ഓണാക്കുക. നിങ്ങൾ ഇപ്പോൾ കണ്ടെത്തിയ ടിക്കറ്റ്, അല്ലെങ്കിൽ അതിന്റെ പ്രോപ്പർട്ടികൾ ക്ലിക്ക് ചെയ്താലും പാനൽ തുറന്നിരിക്കും, അതിനാൽ അതിന്റെ ഫലത്തിൽ നിങ്ങൾ പ്രവർത്തിച്ചാലും ഒരു സെർച്ച് നിലനിൽക്കും.',
        'search_dismiss_label' => 'ഞാൻ ക്ലിക്ക് ചെയ്ത് മാറുമ്പോൾ അടയ്ക്കുക',
        'landing_heading' => 'ആരംഭ പേജ്',
        'workcal_heading' => 'എന്റെ ജോലി കലണ്ടർ',
        'taskcal_heading' => 'ഈ കലണ്ടറിലെ ടാസ്കുകൾ',
        'taskcal_off' => 'ഒന്നുമില്ല',
        'taskcal_work' => 'ഞാൻ ചെയ്യാൻ ആസൂത്രണം ചെയ്യുമ്പോൾ',
        'taskcal_due' => 'അതിന്റെ അവസാന തീയതിയിൽ',
        'taskcal_both' => 'രണ്ടും',
        'taskcal_note' => 'ഒരു ടാസ്കിന് നിങ്ങളുടെ കലണ്ടറിൽ രണ്ട് കാര്യങ്ങൾ ഇടാം: അത് ചെയ്യാൻ നിങ്ങൾ മാറ്റിവച്ച സമയം, ഒരു സാധാരണ appointment ആയി, അതിന്റെ അവസാന തീയതി, ഒരു all-day എൻട്രി ആയി. പൂർത്തിയായ ടാസ്കുകൾ നീക്കം ചെയ്യും, നിങ്ങൾക്ക് പകരം ഒരു ടീമിന് നിയോഗിച്ച ടാസ്ക് ഒരിക്കലും ചേർക്കില്ല.',
        'taskcal_failed' => 'ആ തിരഞ്ഞെടുപ്പ് സേവ് ചെയ്യാൻ കഴിഞ്ഞില്ല',
        'workcal_desc' => 'നിങ്ങൾ ഷെഡ്യൂൾ ചെയ്ത ടിക്കറ്റുകൾ നിങ്ങൾ യഥാർത്ഥത്തിൽ ഉപയോഗിക്കുന്ന കലണ്ടറിൽ ഇടുക — Google, Apple, Outlook അല്ലെങ്കിൽ ഒരു കലണ്ടർ subscribe ചെയ്യാൻ കഴിയുന്ന മറ്റെന്തും.',
        'workcal_off' => 'ഓഫ്',
        'workcal_feed' => 'Subscribe ലിങ്ക്',
        'workcal_push' => 'എന്റെ കലണ്ടറിലേക്ക് ചേർക്കുക',
        'workcal_push_none' => 'ടിക്കറ്റുകൾ നേരിട്ട് നിങ്ങളുടെ കലണ്ടറിലേക്ക് ചേർക്കുന്നത് ലഭ്യമല്ല: ഈ സിസ്റ്റത്തിൽ ഒരു അഡ്മിനിസ്ട്രേറ്റർ ഇതുവരെ ഒരു കലണ്ടർ കണക്ഷൻ സജ്ജീകരിച്ചിട്ടില്ല.',
        'workcal_push_where' => 'നിങ്ങളുടെ ഷെഡ്യൂൾ ചെയ്ത ടിക്കറ്റുകൾ {addr}-ന്റെ കലണ്ടറിലേക്ക് എഴുതപ്പെടും.',
        'workcal_push_bad' => '{addr}-ന് ഒരു കലണ്ടറും കണ്ടെത്താൻ കഴിഞ്ഞില്ല. അതാണ് നിങ്ങളുടെ FreeITSM അക്കൗണ്ടിലെ വിലാസം, അത് എപ്പോഴും നിങ്ങളുടെ മെയിൽബോക്സ് ആയിരിക്കണമെന്നില്ല — നിങ്ങളുടെ കലണ്ടർ സിങ്ക് ശരിയായതിലേക്ക് ചൂണ്ടിക്കാണിക്കാൻ ഒരു അഡ്മിനിസ്ട്രേറ്ററോട് ആവശ്യപ്പെടുക.',
        'workcal_push_noaddr' => 'ഏതാണ് നിങ്ങളുടെ മെയിൽബോക്സ് എന്ന് ഞങ്ങൾക്കറിയില്ല. System → Calendar sync-ൽ ഇത് സെറ്റ് ചെയ്യാൻ ഒരു അഡ്മിനിസ്ട്രേറ്ററോട് ആവശ്യപ്പെടുക.',
        'workcal_conn' => 'ഏത് കലണ്ടർ',
        'workcal_conn_choose' => 'തിരഞ്ഞെടുക്കുക…',
        'workcal_conn_needed' => 'നിങ്ങളുടെ ഷെഡ്യൂൾ ചെയ്ത ജോലി ഏത് കലണ്ടറിലേക്ക് പോകണമെന്ന് തിരഞ്ഞെടുക്കുക.',
        'workcal_push_caldav_where' => 'നിങ്ങളുടെ ഷെഡ്യൂൾ ചെയ്ത ടിക്കറ്റുകൾ നിങ്ങളുടെ "{name}" കലണ്ടറിലേക്ക് എഴുതപ്പെടും.',
        'caldav_intro' => '{server}-ൽ നിങ്ങളുടെ കലണ്ടറിലേക്ക് സൈൻ ഇൻ ചെയ്ത്, നിങ്ങളുടെ ഷെഡ്യൂൾ ചെയ്ത ജോലി ഏത് കലണ്ടറിലേക്ക് പോകണമെന്ന് തിരഞ്ഞെടുക്കുക. FreeITSM നിങ്ങളായി സൈൻ ഇൻ ചെയ്യുന്നു, അതിനാൽ നിങ്ങൾക്ക് എത്താൻ കഴിയുന്ന കലണ്ടറുകളിലേക്ക് മാത്രമേ അതിനും എത്താൻ കഴിയൂ.',
        'caldav_username' => 'ഉപയോക്തൃനാമം',
        'caldav_password' => 'പാസ്‌വേഡ്',
        'caldav_password_hint' => 'നിങ്ങളുടെ കലണ്ടർ പാസ്‌വേഡ്, അല്ലെങ്കിൽ നിങ്ങളുടെ കലണ്ടർ വാഗ്ദാനം ചെയ്യുന്നെങ്കിൽ ഒരു app password - അതാണ് സുരക്ഷിതമായ തിരഞ്ഞെടുപ്പ്. എൻക്രിപ്റ്റ് ചെയ്ത് സൂക്ഷിക്കും, വീണ്ടും കാണിക്കില്ല.',
        'caldav_password_saved' => 'സേവ് ചെയ്തു - അതേപടി നിലനിർത്താൻ ശൂന്യമായി വിടുക',
        'caldav_find' => 'കണ്ടെത്തുക',
        'caldav_finding' => 'നിങ്ങളുടെ കലണ്ടറുകൾ തിരയുന്നു…',
        'caldav_choose' => 'കലണ്ടർ',
        'caldav_none' => 'ആ സൈൻ-ഇൻ വിജയിച്ചു, പക്ഷേ ഇവന്റുകൾ സൂക്ഷിക്കാൻ കഴിയുന്ന ഒരു കലണ്ടറും ഇല്ല.',
        'caldav_needs' => 'സൈൻ ഇൻ ചെയ്ത് ഒരു കലണ്ടർ തിരഞ്ഞെടുക്കുക. ഇത് സേവ് ചെയ്യുന്നത് ഇത് ഓണാക്കും.',
        'caldav_saved' => 'സേവ് ചെയ്തു. നിങ്ങളുടെ ഷെഡ്യൂൾ ചെയ്ത ജോലി "{name}"-ലേക്ക് പോകുന്നു.',
