        'caldav_forget_confirm' => 'FreeITSM അതിന്റെ ഇവന്റുകൾ നിങ്ങളുടെ കലണ്ടറിൽ നിന്ന് തിരികെ എടുക്കും, എന്നിട്ട് നിങ്ങളുടെ സൈൻ-ഇൻ മറന്ന് ഇത് ഓഫ് ചെയ്യും.',
        'workcal_disabled' => 'ഈ സിസ്റ്റത്തിൽ ഒരു അഡ്മിനിസ്ട്രേറ്റർ കലണ്ടർ subscription ലിങ്കുകൾ ഓഫ് ചെയ്തിട്ടുണ്ട്.',
