        'workcal_copied' => 'ലിങ്ക് പകർത്തി',
        'workcal_secret_note' => 'ഇതിനെ ഒരു പാസ്‌വേഡ് പോലെ കൈകാര്യം ചെയ്യുക. ലിങ്ക് ഉള്ള ആർക്കും സൈൻ ഇൻ ചെയ്യാതെ നിങ്ങളുടെ ഷെഡ്യൂൾ ചെയ്ത ജോലി കാണാം, അതിനാൽ അത് ഫോർവേഡ് ചെയ്യരുത്. ഇത് റദ്ദാക്കേണ്ടി വന്നാൽ റീസെറ്റ് ചെയ്യുക.',
        'workcal_insecure' => 'ഈ സിസ്റ്റം HTTPS ഉപയോഗിക്കുന്നില്ല, അതിനാൽ ഈ ലിങ്ക് — അത് കാണിക്കുന്ന എല്ലാം — നിങ്ങളുടെ കലണ്ടർ റിഫ്രഷ് ചെയ്യുമ്പോഴെല്ലാം സംരക്ഷണമില്ലാതെ നെറ്റ്‌വർക്കിലൂടെ സഞ്ചരിക്കുന്നു. വിശ്വസനീയമല്ലാത്ത ഒരു നെറ്റ്‌വർക്കിന് പുറത്ത് ഇത് ഉപയോഗിക്കുന്നതിന് മുമ്പ് HTTPS പ്രവർത്തനക്ഷമമാക്കാൻ നിങ്ങളുടെ അഡ്മിനിസ്ട്രേറ്ററോട് ആവശ്യപ്പെടുക.',
        'workcal_reset_confirm' => 'പുതിയ ലിങ്ക് നൽകുന്നത് വരെ ഇതിനകം subscribe ചെയ്ത ഓരോ ഡിവൈസും അപ്ഡേറ്റ് ആകുന്നത് നിർത്തും. തുടരണോ?',
        'workcal_reset_done' => 'ലിങ്ക് റീസെറ്റ് ചെയ്തു — പഴയത് ഇനി പ്രവർത്തിക്കില്ല',
        'workcal_detail' => 'കലണ്ടർ കാണിക്കുന്നത്',
