        'landing_analyst' => 'അനലിസ്റ്റ് ലോഗിൻ',
        'landing_portal' => 'സെൽഫ്-സർവീസ് പോർട്ടൽ',
        'landing_note' => 'നിങ്ങളുടെ മറ്റ് മുൻഗണനകളിൽ നിന്ന് വ്യത്യസ്തമായി, നിങ്ങൾ ലോഗിൻ ചെയ്യുന്നതിന് മുമ്പ് ഇത് വായിക്കാൻ കഴിയേണ്ടതുണ്ട്, അതിനാൽ ഇത് ഈ ബ്രൗസറിലും സൂക്ഷിക്കും. ഒരു പുതിയ ഡിവൈസിൽ ഉൾപ്പെടെ, നിങ്ങൾ സൈൻ ഇൻ ചെയ്യുന്ന ഓരോ തവണയും ഇത് സ്വയമേവ വീണ്ടും പ്രയോഗിക്കും.',
        'timezone_heading' => 'സമയമേഖല',
        'timezone_desc' => 'നിങ്ങൾക്ക് കാണിക്കുന്നതിന് മുമ്പ് സമയങ്ങൾ ഏത് സമയമേഖലയിലേക്കാണ് പരിവർത്തനം ചെയ്യുന്നത്. നിങ്ങൾ ഒന്ന് തിരഞ്ഞെടുക്കുന്നത് വരെ സെർവർ സമയമേഖല സ്ഥിരസ്ഥിതിയാകും. ഇത് സമയം തന്നെ മാറ്റുന്നു, അത് എങ്ങനെ എഴുതുന്നു എന്നല്ല.',
        'timezone_saved' => 'സമയമേഖല സേവ് ചെയ്തു',
