        'sidebar_heading' => 'സൈഡ്ബാർ',
        'sidebar_desc' => 'വാഫിൾ മെനു തുറക്കുന്നതിന് പകരം, നിങ്ങളുടെ മൊഡ്യൂളുകൾ ഓരോ സ്ക്രീനിന്റെയും ഇടതുവശത്ത് ഒരു ക്ലിക്ക് അകലെ നിലനിർത്തുക. വാഫിൾ എന്തായാലും അവിടെത്തന്നെ ഉണ്ടാകും. ഫോണിൽ കാണിക്കില്ല.',
