        'modorder_note' => 'മാറ്റുന്നതിനൊപ്പം സംരക്ഷിക്കപ്പെടും, നിങ്ങൾ തുറക്കുന്ന അടുത്ത പേജ് മുതൽ ഉപയോഗിക്കും. പിന്നീടുള്ള അപ്ഡേറ്റിൽ ചേർക്കുന്ന മൊഡ്യൂൾ സ്വയം ലിസ്റ്റിൽ ചേരും.',
        'modorder_reset' => 'റീസെറ്റ്',
        'modorder_reset_done' => 'മൊഡ്യൂളുകൾ സ്ഥിരസ്ഥിതി ക്രമത്തിലേക്ക് മടങ്ങി',
        'modorder_saved' => 'മൊഡ്യൂൾ ക്രമം സംരക്ഷിച്ചു',
        'modorder_label' => 'മൊഡ്യൂൾ ക്രമം',
        'money_heading' => 'പണം',
        'money_desc' => 'പണത്തിന്റെ തുകകൾ നിങ്ങൾക്കായി എങ്ങനെ എഴുതുന്നു. ഓരോ റെക്കോർഡിന്റെയും കറൻസി ഒരിക്കലും മാറില്ല - നിങ്ങളുടെ സ്ക്രീനിൽ അതിന്റെ തുക എങ്ങനെ കാണുന്നു എന്നത് മാത്രം.',
        'money_follow' => 'സിസ്റ്റത്തിന്റെ സ്ഥിരസ്ഥിതി ഉപയോഗിക്കുക ({example})',
        'money_own' => 'എന്റെ സ്വന്തം തിരഞ്ഞെടുക്കുക',
        'money_exc_heading' => 'പ്രത്യേക കറൻസികൾ',
        'money_exc_desc' => 'ഒരു കറൻസിക്ക് മാത്രം വ്യത്യസ്ത ഫോർമാറ്റ് - ഉദാഹരണത്തിന്, ബാക്കിയെല്ലാം മുകളിലെ പോലെ തുടരുമ്പോൾ യൂറോ ജർമ്മനിയിൽ എഴുതുന്ന രീതിയിൽ.',
