        'multiselect_desc' => 'ടിക്കറ്റ് ഇൻബോക്സിൽ ഒരേസമയം പല ടിക്കറ്റുകളും തിരഞ്ഞെടുക്കാം — ഓരോന്നായി എടുക്കാൻ Ctrl+click, ഒരു ബ്ലോക്കിന് Shift+click. ഒന്നിലധികം തിരഞ്ഞെടുത്തിരിക്കുമ്പോൾ സ്ക്രീൻ എന്ത് കാണിക്കണമെന്ന് ഇത് തീരുമാനിക്കുന്നു.',
