        'date_heading' => 'തീയതി ഫോർമാറ്റ്',
        'date_desc' => 'ഒരു തീയതി എങ്ങനെ എഴുതണമെന്ന് തിരഞ്ഞെടുക്കുക. ഇത് ക്രമീകരണത്തെക്കുറിച്ച് മാത്രമാണ് - ദിവസം, മാസം, വർഷം എന്നിവ തന്നെ ഒരിക്കലും മാറില്ല, മാസങ്ങളുടെ പേരുകൾ എപ്പോഴും ഇന്റർഫേസ് ഭാഷ പിന്തുടരും.',
        'time_heading' => 'സമയ ഫോർമാറ്റ്',
