        'selfreg_label' => 'Self-registration അനുവദിക്കുക',
        'selfreg_hint' => 'ഓഫ് = ആർക്കും സ്വന്തം അക്കൗണ്ട് സൃഷ്ടിക്കാൻ കഴിയില്ല. നിങ്ങൾ ചേർക്കുന്ന ആളുകൾക്ക് ഇപ്പോഴും സൈൻ ഇൻ ചെയ്യാം — അവർ portal സൈൻ-ഇൻ പേജിലെ "Forgot your password?" ഉപയോഗിച്ച് അവരുടെ ആദ്യ പാസ്‌വേഡ് സെറ്റ് ചെയ്യും.',
        'trusted_heading' => 'വിശ്വസനീയ ഡിവൈസ്',
        'trusted_desc' => 'വിശ്വസനീയ ബ്രൗസറുകളിൽ OTP verification ഒഴിവാക്കാൻ ഉപയോക്താക്കളെ അനുവദിക്കുക. ഉപയോക്താക്കൾ അവരുടെ avatar മെനു വഴി ഓരോരുത്തരായി ഇത് ഓപ്റ്റ് ഇൻ ചെയ്യുന്നു. ഈ ഫീച്ചർ പൂർണ്ണമായും ഓഫ് ചെയ്യാൻ 0 ആയി സെറ്റ് ചെയ്യുക.',
        'trust_duration' => 'വിശ്വാസ കാലാവധി',
        'trust_duration_hint' => 'OTP verification-ന് ശേഷം ഒരു ഡിവൈസ് എത്രനേരം വിശ്വസനീയമായി തുടരും',
        'password_heading' => 'പാസ്‌വേഡ് നയം',
        'password_desc' => 'ഉപയോക്താക്കൾ ഇടയ്ക്കിടെ അവരുടെ പാസ്‌വേഡ് മാറ്റണമെന്ന് നിർബന്ധമാക്കുക. ഒരു പാസ്‌വേഡ് കാലഹരണപ്പെടുമ്പോൾ, അടുത്ത ലോഗിനിൽ ഉപയോക്താവിനെ നിർബന്ധിത പാസ്‌വേഡ് മാറ്റൽ സ്ക്രീനിലേക്ക് റീഡയറക്ട് ചെയ്യും. ഓഫ് ചെയ്യാൻ 0 ആയി സെറ്റ് ചെയ്യുക.',
        'password_expiry' => 'പാസ്‌വേഡ് കാലഹരണം',
        'password_expiry_hint' => 'മാറ്റേണ്ടതിന് മുമ്പ് ഒരു പാസ്‌വേഡിന്റെ പരമാവധി പ്രായം',
        'lockout_heading' => 'അക്കൗണ്ട് ലോക്ക്ഔട്ട്',
        'lockout_desc' => 'Brute-force ആക്രമണങ്ങൾ തടയാൻ ആവർത്തിച്ചുള്ള പരാജയപ്പെട്ട ലോഗിൻ ശ്രമങ്ങൾക്ക് ശേഷം അക്കൗണ്ടുകൾ ലോക്ക് ചെയ്യുക. ലോക്കൗട്ട് ഓഫ് ചെയ്യാൻ max attempts 0 ആയി സെറ്റ് ചെയ്യുക.',
        'max_attempts' => 'പരമാവധി പരാജയപ്പെട്ട ശ്രമങ്ങൾ',
        'max_attempts_hint' => 'അക്കൗണ്ട് ലോക്ക് ചെയ്യുന്നതിന് മുമ്പുള്ള തെറ്റായ പാസ്‌വേഡുകളുടെ എണ്ണം',
        'lockout_duration' => 'ലോക്കൗട്ട് കാലാവധി',
        'lockout_duration_hint' => 'അക്കൗണ്ട് എത്രനേരം ലോക്ക് ആയി തുടരും (unlock ചെയ്തതിന് ശേഷം കൗണ്ടർ റീസെറ്റ് ആകും)',
        'ipban_heading' => 'IP Ban',
        'ipban_desc' => 'നിലവിലില്ലാത്തതോ ലോക്ക് ചെയ്തതോ ആയ അക്കൗണ്ടുകൾക്കെതിരെ ആവർത്തിച്ച് ലോഗിൻ ശ്രമിക്കുന്ന IP വിലാസങ്ങളെ സ്വയമേവ ban ചെയ്യുക. ഓരോ ban-ഉം 24 മണിക്കൂർ നീണ്ടുനിൽക്കും. ഓരോ ban-നും ശേഷം threshold 1 കുറയും (കുറഞ്ഞ പരിധി വരെ), ഇത് ആവർത്തിച്ചുള്ള കുറ്റവാളികൾക്ക് ദുരുപയോഗം ചെയ്യുന്നത് കൂടുതൽ ബുദ്ധിമുട്ടാക്കുന്നു. ഓഫ് ചെയ്യാൻ max attempts 0 ആയി സെറ്റ് ചെയ്യുക.',
        'first_ban' => 'ആദ്യ ban threshold',
        'first_ban_hint' => 'IP ആദ്യമായി ban ചെയ്യുന്നതിന് മുമ്പുള്ള പരാജയപ്പെട്ട ശ്രമങ്ങൾ',
        'min_threshold' => 'കുറഞ്ഞ threshold',
        'min_threshold_hint' => 'ഈ കുറഞ്ഞ പരിധിയിൽ എത്തിക്കഴിഞ്ഞാൽ threshold കുറയുന്നത് നിർത്തും',
        'ipban_example_strong' => 'ഉദാഹരണം:',
        'ipban_example_text' => 'max 5, min 2 ആയിരിക്കുമ്പോൾ, 5 പരാജയപ്പെട്ട ശ്രമങ്ങൾക്ക് ശേഷം ആദ്യ ban, 4-ന് ശേഷം രണ്ടാമത്തേത്, പിന്നെ 3, പിന്നെ 2. തുടർന്നുള്ള ഓരോ ban-നും ഇത് 2-ൽ തുടരും. നിലവിലില്ലാത്ത usernames അല്ലെങ്കിൽ ഇതിനകം ലോക്ക് ചെയ്ത അക്കൗണ്ടുകൾക്കെതിരായ ശ്രമങ്ങൾ മാത്രമേ കണക്കാക്കൂ.',
        'attachments_heading' => 'അറ്റാച്ച്മെന്റുകൾ',
        'attachments_desc' => 'FreeITSM തിരിച്ചറിയുന്ന അറ്റാച്ച്മെന്റ് തരങ്ങൾ മാത്രമേ സ്വീകരിക്കൂ. മറ്റെന്തും — ഒരു പ്രോഗ്രാം, ഒരു സ്ക്രിപ്റ്റ്, ഒരു വെബ് പേജ് — അതിന്റെ സ്വന്തം പേരിൽ ഒരിക്കലും സൂക്ഷിക്കില്ല, അതിനാൽ അത് പ്രവർത്തിപ്പിക്കാൻ കഴിയില്ല.',
        'rejected_behaviour' => 'ഒരു ഫയൽ തരം സ്വീകരിക്കാത്തപ്പോൾ',
        'rejected_behaviour_hint' => 'ഇമെയിൽ, പോർട്ടൽ, chat channels എന്നിവയ്ക്ക് ബാധകം.',
        'rejected_store' => 'സൂക്ഷിക്കുക, ഡൗൺലോഡ് മാത്രം',
        'rejected_drop' => 'സൂക്ഷിക്കരുത്',
        'allowed_extensions' => 'സ്വീകരിക്കുന്ന ഫയൽ തരങ്ങൾ',
        'allowed_extensions_hint' => 'ഭാവി അപ്ഡേറ്റുകൾ ചേർക്കുന്ന പുതിയ തരങ്ങൾ ഉൾപ്പെടെ, FreeITSM സുരക്ഷിതമെന്ന് കരുതുന്ന എല്ലാം സ്വീകരിക്കാൻ ശൂന്യമായി വിടുക. കുറച്ച് സ്വീകരിക്കാൻ, നിങ്ങൾക്ക് വേണ്ട extensions മാത്രം കോമ കൊണ്ട് വേർതിരിച്ച് ലിസ്റ്റ് ചെയ്യുക.',
        'allowed_extensions_ph' => 'e.g. pdf, docx, xlsx, png, jpg',
        'allowed_extensions_note' => 'ഈ ലിസ്റ്റ് ചുരുക്കാൻ മാത്രമേ കഴിയൂ. FreeITSM ഇതിനകം സുരക്ഷിതമെന്ന് കരുതാത്ത ഒരു extension അവഗണിക്കും, അതിനാൽ ഇവിടെ ടൈപ്പ് ചെയ്യുന്നതൊന്നും ഒരു പ്രോഗ്രാമിനെയോ സ്ക്രിപ്റ്റിനെയോ സ്വീകാര്യമാക്കില്ല.',
        'rejected_note' => 'ഏത് വിധേനയും, എന്ത് സംഭവിച്ചു, എന്തുകൊണ്ട് എന്ന് ടിക്കറ്റ് പറയുന്നു, അതിനാൽ അവരുടെ ഫയൽ എവിടെ പോയി എന്ന് ആരും ആശ്ചര്യപ്പെടേണ്ടതില്ല.',
        'max_attachment' => 'ഏറ്റവും വലിയ അറ്റാച്ച്മെന്റ്',
        'max_attachment_hint' => 'ഒരു അറ്റാച്ച്മെന്റും ഇതിനേക്കാൾ വലുതാകരുത് - ഇമെയിൽ, പോർട്ടൽ, ചാറ്റ് ചാനലുകൾ, മറുപടികൾ, അറ്റാച്ച് ചെയ്ത പ്രമാണങ്ങൾ എന്നിവയിൽ. മാറ്റുന്നില്ലെങ്കിൽ 10 MB.',
        'max_total' => 'ഏറ്റവും വലിയ ഇമെയിൽ',
        'max_total_hint' => 'ഒരു ഇൻബൗണ്ട് ഇമെയിലിലെ എല്ലാ അറ്റാച്ച്മെന്റുകളും ചേർത്ത്. 0 എന്നാൽ മുകളിലേതിനപ്പുറം പരിധിയില്ല.',
        'php_limits' => 'ഈ സെർവറിലെ PHP ബ്രൗസർ അപ്‌ലോഡുകൾ ഒരു ഫയലിന് {upload} വരെയും ഒരു അഭ്യർത്ഥനയ്ക്ക് {post} വരെയും സ്വീകരിക്കുന്നു (php.ini-യിലെ upload_max_filesize, post_max_size), പ്രവർത്തിക്കാൻ {memory} മെമ്മറിയും ഉണ്ട്. PHP നിരസിക്കുന്ന ഫയൽ FreeITSM-ൽ എത്തില്ല, അതിനാൽ ഇവയ്ക്ക് മുകളിലുള്ള പരിധി ഇമെയിലിന് മാത്രമേ ഉപകരിക്കൂ. മുന്നിലുള്ള ഒരു വെബ് സെർവറിനോ പ്രോക്സിക്കോ (nginx client_max_body_size, IIS maxAllowedContentLength) സ്വന്തമായി കുറഞ്ഞ പരിധി വയ്ക്കാം.',
        'php_limits_warn' => 'ഏറ്റവും വലിയ അറ്റാച്ച്മെന്റ് PHP ഒരു ബ്രൗസറിൽ നിന്ന് സ്വീകരിക്കുന്നതിലും കൂടുതലാണ്: php.ini-യിലെ upload_max_filesize, post_max_size എന്നിവയും ഉയർത്തുക, അല്ലെങ്കിൽ FreeITSM വഴി അപ്‌ലോഡ് ചെയ്യുന്ന ഫയലുകൾ എത്തുന്നതിന് മുമ്പേ നിരസിക്കപ്പെടും.',
        'php_unlimited' => 'പരിധിയില്ല',
        'oversize_signpost' => 'ഈ പരിധികൾക്ക് മുകളിലുള്ള ഇൻബൗണ്ട് ഇമെയിലിന് എന്ത് സംഭവിക്കും - നിരസിക്കുക, അല്ലെങ്കിൽ വലുപ്പം കൂടിയ അറ്റാച്ച്മെന്റുകൾ ഒഴിവാക്കി സൂക്ഷിക്കുക, ആരെ അറിയിക്കും എന്നിവ - {link}-ൽ സജ്ജമാക്കുന്നു. ഓരോ മെയിൽബോക്സിനും അവിടെ സ്വന്തം പരിധികളും വയ്ക്കാം.',
        'oversize_signpost_link' => 'Tickets -> Settings -> Mailboxes',
        'unit_days' => 'ദിവസങ്ങൾ',
        'unit_attempts' => 'ശ്രമങ്ങൾ',
        'unit_minutes' => 'മിനിറ്റുകൾ',
        'save' => 'സംരക്ഷിക്കുക',
        'saved' => 'സുരക്ഷാ ക്രമീകരണങ്ങൾ സേവ് ചെയ്തു',
        'error' => 'പിശക്: {error}',
        'save_failed' => 'ക്രമീകരണങ്ങൾ സേവ് ചെയ്യാൻ കഴിഞ്ഞില്ല',
