    'sso' => [
        'title' => 'Authentication',
        'subtitle' => 'Keycloak, Microsoft Entra, Okta അല്ലെങ്കിൽ Google പോലുള്ള ഒരു external identity provider (OpenID Connect) വഴിയോ, നിങ്ങളുടെ LDAP / Active Directory വഴിയോ ഉപയോക്താക്കളെ സൈൻ ഇൻ ചെയ്യാൻ അനുവദിക്കുക — ലോക്കൽ അക്കൗണ്ടുകൾക്കൊപ്പം.',
        'global_heading' => 'ആഗോള ക്രമീകരണങ്ങൾ',
        'global_desc' => 'മുഴുവൻ സിസ്റ്റത്തിലുടനീളമുള്ള സൈൻ-ഓണിനുള്ള മാസ്റ്റർ നിയന്ത്രണങ്ങൾ.',
        'enable_sso' => 'Single sign-on പ്രവർത്തനക്ഷമമാക്കുക',
        'enable_sso_desc' => 'ലോഗിൻ പേജിൽ സജ്ജീകരിച്ച provider ബട്ടണുകൾ കാണിക്കുക. എല്ലായിടത്തും ഉടനടി ലോക്കൽ ലോഗിനിലേക്ക് മടങ്ങാൻ ഇത് ഓഫ് ചെയ്യുക (break-glass).',
        'allow_local' => 'ലോക്കൽ ലോഗിൻ അനുവദിക്കുക',
        'allow_local_desc' => 'ഉപയോക്തൃനാമം + പാസ്‌വേഡ് ഫോം ലഭ്യമായി നിലനിർത്തുക. തെറ്റായി സജ്ജീകരിച്ചതോ പ്രവർത്തിക്കാത്തതോ ആയ ഒരു provider എല്ലാവരെയും പുറത്താക്കാതിരിക്കാൻ ഇത് ഓണായി വയ്ക്കുക.',
        'global_load_failed' => 'ഈ ക്രമീകരണങ്ങൾ വായിക്കാൻ കഴിഞ്ഞില്ല.',
        'global_load_failed_desc' => 'താഴെയുള്ള സ്വിച്ചുകൾ നിങ്ങളുടെ യഥാർത്ഥ ക്രമീകരണങ്ങൾ കാണിക്കുന്നില്ല, അതിനാൽ തെറ്റായ ഒരു മൂല്യം മുകളിൽ സേവ് ചെയ്യപ്പെടാതിരിക്കാൻ അവ ലോക്ക് ചെയ്തിരിക്കുന്നു. ഒന്നും മാറിയിട്ടില്ല.',
        'retry' => 'വീണ്ടും ശ്രമിക്കുക',
        'save' => 'സംരക്ഷിക്കുക',
        'redirect_heading' => 'Redirect URI',
        'redirect_desc' => 'ഈ കൃത്യമായ URL ഓരോ identity provider-ലും അനുവദനീയമായ redirect / callback URL ആയി രജിസ്റ്റർ ചെയ്യുക. ഉപയോക്താക്കൾ സൈൻ ഇൻ ചെയ്തതിന് ശേഷം provider അവരെ തിരികെ അയയ്ക്കുന്ന ഇടമാണിത്.',
        'signout_heading' => 'സൈൻ-ഔട്ട് വിലാസങ്ങൾ',
        'signout_desc' => 'രണ്ടും ഓരോ ഐഡന്റിറ്റി പ്രൊവൈഡറിലും അനുവദനീയമായ സൈൻ-ഔട്ട് (പോസ്റ്റ്-ലോഗൗട്ട്) റീഡയറക്ട് URL-കളായി രജിസ്റ്റർ ചെയ്യുക. FreeITSM-ൽ നിന്ന് സൈൻ ഔട്ട് ചെയ്യുമ്പോൾ ആളുകൾ പ്രൊവൈഡറിൽ നിന്നും സൈൻ ഔട്ട് ആകും, തുടർന്ന് പ്രൊവൈഡർ അവരെ ഇവയിലൊന്നിലേക്ക് തിരിച്ചയയ്ക്കും. പട്ടികപ്പെടുത്തിയിട്ടില്ലാത്ത ഏത് വിലാസവും Keycloak-ഉം Okta-യും നിരസിക്കും.',
        'signout_analyst' => 'അനലിസ്റ്റ് ലോഗിൻ',
        'signout_portal' => 'സെൽഫ്-സർവീസ് പോർട്ടൽ',
        'copy' => 'പകർത്തുക',
        'providers_heading' => 'സൈൻ-ഇൻ രീതികൾ',
        'providers_desc' => 'നിങ്ങളുടെ ആളുകൾ എവിടെ നിന്ന് വരുന്നു. മിക്ക വരികളും സൈൻ ഇൻ ചെയ്യാനുള്ള ഒരു വഴിയാണ് — ഒരു identity provider (SSO) അല്ലെങ്കിൽ ഒരു directory (LDAP) — സമാന്തരമായി pilots നടത്താൻ വ്യത്യസ്ത ഉപയോക്താക്കളെ വ്യത്യസ്ത രീതികളിലേക്ക് നിയോഗിക്കാം. ഒരു CardDAV address book ഒരു അപവാദമാണ്: അത് contacts കൊണ്ടുവരുന്നു, ആരും ഇതിലൂടെ സൈൻ ഇൻ ചെയ്യുന്നില്ല.',
