        'field_display_name_hint_carddav' => 'നിങ്ങളുടെ സ്വന്തം റഫറൻസിനായി ഒരു പേര് മാത്രം, ഉദാ. "Customer address book". ഇത് ലോഗിൻ പേജിൽ ഒരിക്കലും ദൃശ്യമാകില്ല — ഒരു address book വഴി ആരും സൈൻ ഇൻ ചെയ്യുന്നില്ല.',
