        'field_scopes' => 'Scopes',
        'field_scopes_hint' => 'സ്പേസ് കൊണ്ട് വേർതിരിച്ച OIDC scopes. നിങ്ങളുടെ provider-ന് കൂടുതൽ ആവശ്യമില്ലെങ്കിൽ സ്ഥിരസ്ഥിതിയായി വിടുക.',
        'cb_enabled' => 'പ്രവർത്തനക്ഷമം',
        'cb_enabled_desc' => 'ഈ provider-ന്റെ ബട്ടൺ ലോഗിൻ പേജിൽ കാണിക്കുക',
        'cb_enabled_desc_carddav' => 'ഈ address book ഉപയോഗിക്കുക. ക്രമീകരണങ്ങൾ ഇല്ലാതാക്കാതെ ഇതിൽ നിന്ന് contacts വായിക്കുന്നത് നിർത്താൻ ഇത് ഓഫ് ചെയ്യുക.',
        'cb_autocreate' => 'ആദ്യ ലോഗിനിൽ ഉപയോക്താക്കളെ സ്വയമേവ സൃഷ്ടിക്കുക (JIT)',
        'cb_autocreate_desc' => 'ഈ provider വഴി ആരെങ്കിലും ആദ്യമായി സൈൻ ഇൻ ചെയ്യുമ്പോൾ ഒരു അനലിസ്റ്റിനെ സ്വയമേവ സൃഷ്ടിക്കുക. മുൻകൂട്ടി സൃഷ്ടിച്ച ഉപയോക്താക്കൾക്ക് മാത്രം പ്രവേശിക്കാവുന്ന, കർശനമായി നിയന്ത്രിച്ച pilots-ന് ഇത് ഓഫ് ആയി വിടുക.',
        'cb_autocreate_users' => 'ആദ്യ ലോഗിനിൽ പോർട്ടൽ അഭ്യർത്ഥകരെ സ്വയം സൃഷ്ടിക്കുക (JIT)',
        'cb_autocreate_users_desc' => 'ഒരു എൻഡ് യൂസർ ഈ പ്രൊവൈഡർ വഴി ആദ്യമായി സൈൻ ഇൻ ചെയ്യുമ്പോൾ സെൽഫ്-സർവീസ് പോർട്ടൽ അക്കൗണ്ട് സ്വയമേവ സൃഷ്ടിക്കുക.',
        'cb_autocreate_analysts' => 'ആദ്യ ലോഗിനിൽ IT അനലിസ്റ്റുകളെ സ്വയം സൃഷ്ടിക്കുക (JIT)',
        'cb_autocreate_analysts_desc' => 'അനലിസ്റ്റ് ലോഗിൻ സ്ക്രീനിലെ ആദ്യ സൈൻ-ഇനുകൾക്ക് അനലിസ്റ്റ് അക്കൗണ്ടുകൾ സൃഷ്ടിക്കാൻ അനുവദിക്കുക. അനലിസ്റ്റുകളെ കൈകൊണ്ട് സൃഷ്ടിക്കണമെങ്കിൽ ഇത് പ്രവർത്തനരഹിതമാക്കി വയ്ക്കുക.',
        'field_fallback_mode' => 'അനലിസ്റ്റ് അല്ലാത്തവരുടെ സൈൻ-ഇൻ നടപടി',
        'field_fallback_mode_hint' => 'IT അനലിസ്റ്റ് അക്കൗണ്ട് ഇല്ലാത്ത ഒരാൾ അനലിസ്റ്റ് ലോഗിൻ സ്ക്രീനിൽ സൈൻ ഇൻ ചെയ്യുമ്പോൾ എടുക്കുന്ന നടപടി.',
        'fallback_mode_confirm' => 'സെൽഫ്-സർവീസ് പോർട്ടലിലേക്ക് മാറുന്നതിന് മുമ്പ് മുന്നറിയിപ്പ് നൽകി സ്ഥിരീകരിക്കുക',
        'fallback_mode_redirect' => 'സെൽഫ്-സർവീസ് പോർട്ടലിലേക്ക് സ്വയം മാറുക',
        'fallback_mode_block' => 'ആക്സസ് നിരസിച്ച പിശകോടെ സൈൻ-ഇൻ തടയുക',
        'cb_verified' => 'ഒരു verified-email claim ആവശ്യപ്പെടുക',
        'cb_verified_desc' => 'Provider {claim} അയയ്ക്കാത്തപക്ഷം സൈൻ-ഇൻ നിരസിക്കുക. claim തീർത്തും ഒഴിവാക്കുന്ന providers-ന് (ഉദാ. Okta-യുടെ org server) ഇത് ഓഫ് ആയി വിടുക. ഈ ക്രമീകരണം എന്തായാലും വ്യക്തമായ {claim_false} എപ്പോഴും നിരസിക്കപ്പെടും. ഉപയോക്താക്കൾക്ക് സ്ഥിരീകരിക്കാത്ത വിലാസങ്ങൾ ഉപയോഗിച്ച് സ്വയം രജിസ്റ്റർ ചെയ്യാവുന്ന IdPs-ന് മാത്രം ഇത് ഓണാക്കുക.',
        'field_profile_sync_mode' => 'പ്രൊഫൈൽ ആട്രിബ്യൂട്ട് സിങ്ക്',
        'field_profile_sync_mode_hint' => 'സൈൻ-ഇൻ സമയത്ത് IdP ക്ലെയിമുകളിൽ നിന്ന് ഉപയോക്തൃ പ്രൊഫൈൽ ആട്രിബ്യൂട്ടുകൾ (പേര്, തലക്കെട്ട്, വകുപ്പ്, ഓഫീസ്, ഫോൺ) എങ്ങനെ അപ്ഡേറ്റ് ചെയ്യുന്നു.',
        'profile_sync_always' => 'സൈൻ-ഇനിൽ എപ്പോഴും IdP-യിൽ നിന്ന് സിങ്ക് ചെയ്യുക',
        'profile_sync_initial' => 'അക്കൗണ്ട് സൃഷ്ടിക്കുമ്പോൾ സിങ്ക് ചെയ്യുക, പിന്നീട് ലോക്കൽ എഡിറ്റുകൾ അനുവദിക്കുക',
        'profile_sync_never' => 'ആട്രിബ്യൂട്ടുകൾ ഒരിക്കലും സിങ്ക് ചെയ്യരുത് (പ്രൊഫൈൽ ലോക്കലായി മാനേജ് ചെയ്യുക)',
        'field_default_modules' => 'സ്വയം സൃഷ്ടിച്ച അനലിസ്റ്റുകൾക്കുള്ള സ്ഥിര മൊഡ്യൂൾ ആക്സസ്',
        'field_jit_company' => 'സ്വയം സൃഷ്ടിച്ച അനലിസ്റ്റുകൾക്കുള്ള കമ്പനി ആക്സസ്',
        'field_jit_company_hint' => 'ഈ പ്രൊവൈഡർ സൃഷ്ടിച്ച അനലിസ്റ്റിന് ഏതൊക്കെ കമ്പനികൾ കാണാം. അക്കൗണ്ട് സൃഷ്ടിക്കുമ്പോൾ മാത്രമേ ഇത് ബാധകമാകൂ; പിന്നീട് System → Analysts-ൽ മാറ്റുക.',
        'jit_company_all' => 'എല്ലാ കമ്പനികളും (മുമ്പത്തെപ്പോലെ)',
        'jit_company_provider' => 'ഈ പ്രൊവൈഡറിന്റെ കമ്പനി മാത്രം (ഗ്ലോബൽ പ്രൊവൈഡറിന് Default കമ്പനി)',
        'jit_company_none' => 'ഒരു അഡ്മിനിസ്ട്രേറ്റർ നൽകുന്നതുവരെ ഒന്നുമില്ല',
        'tab_groups' => 'ഗ്രൂപ്പുകളും ടീമുകളും',
        'tab_portal' => 'പോർട്ടലും കമ്പനിയും',
        'claims_intro' => 'ഓപ്ഷണൽ. ആർക്ക് അനലിസ്റ്റ് ആകാം, ആരാണ് അഡ്മിനിസ്ട്രേറ്റർ, ആളുകൾ ഏതൊക്കെ ടീമുകളിലാണ് എന്ന് തീരുമാനിക്കാൻ നിങ്ങളുടെ ഐഡന്റിറ്റി പ്രൊവൈഡർ അയയ്ക്കുന്ന ഗ്രൂപ്പുകൾ ഉപയോഗിക്കുക. ഓരോ സൈൻ-ഇനിലും വീണ്ടും പരിശോധിക്കുന്നതിനാൽ ആക്സസ് ഐഡന്റിറ്റി പ്രൊവൈഡറെ പിന്തുടരും. ഒരു ടീമിന് എന്തു ചെയ്യാമെന്നത് System → Teams-ൽ സജ്ജമാക്കുന്നു.',
        'field_group_claim' => 'ഗ്രൂപ്പുകൾ എവിടെ നിന്ന് വരുന്നു',
        'field_group_claim_hint' => 'ഗ്രൂപ്പുകൾ പട്ടികപ്പെടുത്തുന്ന സൈൻ-ഇനിലെ ഭാഗം. മിക്ക പ്രൊവൈഡർമാരും ഇതിനെ groups എന്ന് വിളിക്കുന്നു; Keycloak realm_access.roles ഉപയോഗിക്കുന്നു. ഇത് അയയ്ക്കാൻ നിങ്ങളുടെ പ്രൊവൈഡർ സജ്ജമാക്കേണ്ടി വന്നേക്കാം - സഹായം കാണുക.',
