        'carddav_pick_all' => 'എല്ലാം തിരഞ്ഞെടുക്കുക',
        'carddav_pick_none' => 'മായ്ക്കുക',
        'carddav_pick_summary' => 'തിരഞ്ഞെടുത്തത്: {n}',
        'carddav_pick_summary_none' => 'ഇതുവരെ ഒന്നും തിരഞ്ഞെടുത്തിട്ടില്ല.',
        'carddav_write_heading' => 'മാറ്റങ്ങൾ തിരികെ അയയ്ക്കൽ',
        'carddav_write_hint' => 'സാധാരണയായി FreeITSM ഈ address book വായിക്കുക മാത്രമേ ചെയ്യൂ. ഇത് ഓണാക്കിയാൽ, ഒരു contact-ന്റെ job title, department, office, phone അല്ലെങ്കിൽ mobile എന്നിവയിൽ ഒരു അനലിസ്റ്റ് വരുത്തുന്ന മാറ്റം അവരുടെ കാർഡിലേക്കും എഴുതപ്പെടും. അവരുടെ employee ID-യും manager-ഉം FreeITSM-ൽ തന്നെ നിലനിൽക്കും, കാരണം ഒരു contact card-ൽ അവ സൂക്ഷിക്കാൻ ഇടമില്ല.',
        'carddav_write_back' => 'FreeITSM-ൽ വരുത്തിയ മാറ്റങ്ങൾ address book-ലേക്ക് തിരികെ എഴുതുക',
        'carddav_allow_create' => 'ഈ address book-ലേക്ക് ആളുകളെ ചേർക്കാൻ അനലിസ്റ്റുകളെ അനുവദിക്കുക',
        'carddav_allow_create_hint' => 'സ്ഥിരസ്ഥിതിയായി ഓഫ്. ഇത് ഓണാക്കിയാൽ, ഒരു address book-ലും ഇല്ലാത്ത ഒരാൾക്ക് Tickets, Assets എന്നിവയിൽ Add to address book ബട്ടൺ ലഭിക്കും, ഇത് ഇവിടെ അവരുടെ കാർഡ് സൃഷ്ടിച്ച് അവരെ ലിങ്ക് ചെയ്യുന്നു. എന്തെങ്കിലും എഴുതുന്നതിന് മുമ്പ്, book-ൽ ആർക്കും ഇതിനകം അവരുടെ ഇമെയിൽ വിലാസം ഇല്ലെന്ന് FreeITSM പരിശോധിക്കുന്നു, അതിന് ശേഷം പുതിയ കാർഡ് ഈ source ഇംപോർട്ട് ചെയ്യുന്ന ഒന്നാണെന്ന് — അത് ഇംപോർട്ട് ചെയ്യുന്ന tag അല്ലെങ്കിൽ group ചേർത്ത് — പരിശോധിക്കുകയും അല്ലെങ്കിൽ അത് വീണ്ടും നീക്കം ചെയ്യുകയും ചെയ്യുന്നു.',
        'carddav_write_warning' => 'മുകളിൽ പറഞ്ഞ വിശദാംശങ്ങൾ മാത്രമേ മാറുകയുള്ളൂ, എഡിറ്റ് ചെയ്യുന്ന contact-ൽ മാത്രം. കാർഡിലെ മറ്റെല്ലാം — photo, notes, birthday, full address, groups — അതേപടി നിലനിർത്തും. FreeITSM അവസാനമായി ഇംപോർട്ട് ചെയ്തതിന് ശേഷം ആരെങ്കിലും address book-ൽ അതേ വിശദാംശം മാറ്റിയിട്ടുണ്ടെങ്കിൽ, അവരുടേത് overwrite ചെയ്യാതെ മാറ്റം നിരസിക്കും.',
        'carddav_write_check' => 'അനുമതി പരിശോധിക്കുക',
        'carddav_write_checking' => 'സെർവറിനോട് ചോദിക്കുന്നു…',
        'carddav_write_check_failed' => 'അനുമതി പരിശോധന പൂർത്തിയാക്കാൻ കഴിഞ്ഞില്ല.',
        'carddav_writelog_heading' => 'തിരികെ അയച്ച മാറ്റങ്ങൾ',
        'carddav_writelog_hint' => 'FreeITSM ഒരു contact card അപ്ഡേറ്റ് ചെയ്യാൻ ശ്രമിച്ച ഓരോ തവണയും, എന്ത് സംഭവിച്ചു എന്നും. നിരസിച്ച ഒരു മാറ്റം ഒരു തകരാറല്ല — അത് അർത്ഥമാക്കുന്നത് ആരെങ്കിലും address book-ൽ അതേ വിശദാംശം ഇതിനകം മാറ്റിയിരുന്നു എന്നും FreeITSM അത് overwrite ചെയ്തില്ല എന്നുമാണ്.',
