        'carddav_run_failed' => 'ഇംപോർട്ട് നടത്താൻ കഴിഞ്ഞില്ല.',
        'carddav_run_confirm_all' => 'ഇത് ആ address book-ലെ എല്ലാ contact-നെയും നിങ്ങളുടെ service desk-ലേക്ക് കൊണ്ടുവരികയും, അതിൽ നിന്ന് അവരെ അപ്ഡേറ്റ് ആയി നിലനിർത്തുകയും ചെയ്യും. അതേ ഇമെയിൽ വിലാസമുള്ള ഇവിടെ ഇതിനകം ഉള്ളവരെ ഇതിലേക്ക് ലിങ്ക് ചെയ്യും. ആരെയും ഒരിക്കലും ഇല്ലാതാക്കില്ല.',
        'carddav_run_confirm_scoped' => 'ഇത് നിങ്ങൾ തിരഞ്ഞെടുത്ത contacts നിങ്ങളുടെ service desk-ലേക്ക് കൊണ്ടുവരികയും, address book-ൽ നിന്ന് അവരെ അപ്ഡേറ്റ് ആയി നിലനിർത്തുകയും ചെയ്യും. അതേ ഇമെയിൽ വിലാസമുള്ള ഇവിടെ ഇതിനകം ഉള്ളവരെ ഇതിലേക്ക് ലിങ്ക് ചെയ്യും. ആരെയും ഒരിക്കലും ഇല്ലാതാക്കില്ല.',
        'carddav_history_hint' => 'ഓരോ ഇംപോർട്ടും, അത് എന്ത് ചെയ്തു എന്നും. stopped എന്ന് കാണിക്കുന്ന ഒരു run safety check നിർത്തിയതാണ്, അതായത് ഒന്നും മാറിയിട്ടില്ല.',
