        'carddav_test_auth' => 'സെർവർ {scheme} authentication ഉപയോഗിക്കുന്നു.',
        'carddav_test_pick' => 'മുകളിൽ Address book-ൽ ഒന്ന് തിരഞ്ഞെടുക്കുക, എന്നിട്ട് Save ചെയ്യുക.',
        'field_carddav_scope' => 'ഏതൊക്കെ contacts കൊണ്ടുവരണം',
        'field_carddav_scope_hint' => 'Address books-ൽ പലപ്പോഴും നിങ്ങളുടെ service desk-ൽ വേണ്ടതിലും കൂടുതൽ ഉണ്ടാകും. Test connection അമർത്തുക, FreeITSM നിങ്ങൾ തിരഞ്ഞെടുത്ത book-നുള്ളിൽ നോക്കി കണ്ടെത്തുന്നത് വാഗ്ദാനം ചെയ്യും — groups, tags, അല്ലെങ്കിൽ എല്ലാം.',
        'carddav_scope_all' => 'ഈ address book-ലെ എല്ലാം',
