        'carddav_scope_category_none' => 'ഒരു പ്രത്യേക tag ഉള്ള contacts മാത്രം (ഈ address book-ൽ ഒന്നുമില്ല)',
        'field_carddav_scope_value' => 'ഏതാണ്',
