        'carddav_scope_untested' => 'ഈ address book-ൽ എന്താണെന്ന് കാണാൻ Test connection അമർത്തുക',
        'carddav_scope_untested_hint' => 'അതിൽ എന്താണെന്ന് കണ്ടെത്താൻ FreeITSM address book വായിക്കുന്നു, അതിനാൽ ടെസ്റ്റ് ചെയ്ത ശേഷം ഇത് നിറയും.',
        'carddav_scope_none' => 'ഈ address book-ൽ ഒന്നുമില്ല',
        'carddav_scope_none_hint' => 'FreeITSM address book വായിച്ചു, ഇവയൊന്നും കണ്ടെത്തിയില്ല, അതിനാൽ തിരഞ്ഞെടുക്കാൻ ഒന്നുമില്ല. പകരം "Everything in this address book" തിരഞ്ഞെടുക്കുക, അല്ലെങ്കിൽ ആദ്യം നിങ്ങളുടെ address book സെർവറിൽ grouping സജ്ജീകരിക്കുക.',
        'carddav_scope_required' => 'ഏത് group അല്ലെങ്കിൽ tag കൊണ്ടുവരണമെന്ന് തിരഞ്ഞെടുക്കുക, അല്ലെങ്കിൽ address book-ലെ എല്ലാത്തിലേക്കും തിരികെ മാറുക.',
        'carddav_book_changed' => 'Address book മാറി — അതിനുള്ളിൽ എന്താണെന്ന് കാണാൻ വീണ്ടും Test connection അമർത്തുക.',
        'carddav_test_scan' => 'ആ address book-നുള്ളിൽ നോക്കി — contacts: {contacts}, groups: {groups}, tags: {categories}.',
