        'ldap_preset_hint' => 'നിങ്ങളുടെ directory-ക്കുള്ള പതിവ് filter, attribute പേരുകൾ പൂരിപ്പിക്കുന്നു. താഴെയുള്ള എന്തും ഇപ്പോഴും മാറ്റാം.',
