        'ldap_enc_hint' => 'ഓരോ സൈൻ-ഇന്നിലും പാസ്‌വേഡുകൾ നെറ്റ്‌വർക്ക് കടക്കുന്നു. Production-ൽ STARTTLS അല്ലെങ്കിൽ LDAPS ഉപയോഗിക്കുക — എന്തായാലും പല Active Directory സെർവറുകളും plain LDAP-ലൂടെയുള്ള password binds നിരസിക്കുന്നു.',
        'field_ldap_bind_dn' => 'Service account',
        'field_ldap_bind_dn_hint' => 'ഉപയോക്താക്കളെ നോക്കാൻ bind ചെയ്യുന്ന ഒരു read-only അക്കൗണ്ട് — ആളുകൾ ഇങ്ങനെയല്ല സൈൻ ഇൻ ചെയ്യുന്നത്. Active Directory user@domain സ്വീകരിക്കുന്നു; OpenLDAP-ന് cn=svc,dc=example,dc=com പോലെ ഒരു പൂർണ്ണ DN വേണം. അജ്ഞാതമായി തിരയാൻ ശൂന്യമായി വിടുക (അപൂർവ്വമായേ അനുവദിക്കൂ).',
        'field_ldap_bind_password' => 'Service account പാസ്‌വേഡ്',
