        'sync_heading' => 'ഈ directory-യിൽ നിന്ന് ആളുകളെ ഇംപോർട്ട് ചെയ്യുക',
        'sync_desc' => 'സൈൻ ഇൻ ചെയ്യുന്നത് ഒരാളെ അവർ ആദ്യം ലോഗിൻ ചെയ്യുമ്പോൾ മാത്രമേ സൃഷ്ടിക്കൂ. Importing എല്ലാവരെയും മുൻകൂട്ടി കൊണ്ടുവരുന്നു, അതിനാൽ ഒരിക്കലും സൈൻ ഇൻ ചെയ്യാത്ത ആളുകൾക്കുപോലും equipment നിയോഗിക്കാം.',
        'sync_enabled' => 'ഈ directory-യിൽ നിന്ന് ആളുകളെ ഇംപോർട്ട് ചെയ്യുക',
        'sync_base_dn_hint' => 'directory-യുടെ ഏത് ഭാഗത്ത് നിന്ന് ഇംപോർട്ട് ചെയ്യണം. സൈൻ-ഇൻ തിരയുന്ന അതേ സ്ഥലം ഉപയോഗിക്കാൻ ശൂന്യമായി വിടുക — മുഴുവൻ directory-ക്കും എതിരെ authenticate ചെയ്യുന്നു, പക്ഷേ അതിന്റെ ഒരു ഭാഗം മാത്രം ഇംപോർട്ട് ചെയ്യണമെങ്കിൽ ഇത് സെറ്റ് ചെയ്യുക.',
        'sync_base_dn_placeholder' => 'OU=Staff,OU=Company,DC=example,DC=com',
