        'sync_conflict_hint' => 'അതേ ഇമെയിൽ വിലാസത്തോടെ FreeITSM-ൽ ഇതിനകം ഉള്ള ഒരാൾ directory-യിൽ ഉണ്ടെങ്കിൽ. Adopt ചെയ്യുന്നത് അവരെ directory-യിലേക്ക് ലിങ്ക് ചെയ്യുന്നു — അതിന് ശേഷം അവരുടെ FreeITSM portal പാസ്‌വേഡ് പ്രവർത്തിക്കില്ല, പകരം അവർ directory വഴി സൈൻ ഇൻ ചെയ്യും.',
