        'sync_conflict_flag' => 'അവരെ വെറുതെ വിട്ട് എനിക്കായി ഫ്ലാഗ് ചെയ്യുക',
        'sync_safety' => 'സുരക്ഷ',
        'sync_deactivate_hint' => 'directory-യിൽ നിന്ന് ഇത്രയും imports തുടർച്ചയായി കാണാതായ ശേഷം ഒരാളെ വിട്ടുപോയതായി അടയാളപ്പെടുത്തുക. ആരെയും ഒരിക്കലും ഇല്ലാതാക്കില്ല. ആളുകളെ ഒരിക്കലും സ്വയമേവ വിട്ടുപോയതായി അടയാളപ്പെടുത്താതിരിക്കാൻ 0 ആയി സെറ്റ് ചെയ്യുക.',
        'sync_brake_hint' => 'ഒരു ഇംപോർട്ട് കഴിഞ്ഞ തവണത്തേക്കാൾ ഇത്ര ശതമാനം കുറച്ച് ആളുകൾ കണ്ടെത്തിയാൽ ഒന്നും മാറ്റാതെ നിർത്തുക. തെറ്റായ ഒരു ക്രമീകരണമോ directory പ്രശ്നമോ എല്ലാവരും ഒരുമിച്ച് വിട്ടുപോകുന്നത് പോലെ കാണപ്പെടും, ഇത് നിങ്ങളുടെ ലിസ്റ്റ് ശൂന്യമാകുന്നത് തടയുന്നു. പരിശോധന ഓഫ് ചെയ്യാൻ 0 ആയി സെറ്റ് ചെയ്യുക.',
