        'sync_confirm' => 'ഈ directory-യിൽ നിന്ന് ഇപ്പോൾ ആളുകളെ ഇംപോർട്ട് ചെയ്യണോ? ഇത് ആളുകളെ ചേർക്കുകയും അപ്ഡേറ്റ് ചെയ്യുകയും, ചിലരെ വിട്ടുപോയതായി അടയാളപ്പെടുത്തുകയും ചെയ്തേക്കാം. ആരെയും ഒരിക്കലും ഇല്ലാതാക്കില്ല.',
