        'ou_tree_hint' => 'ഇംപോർട്ട് ചെയ്യേണ്ട directory-യുടെ ഭാഗങ്ങൾ ടിക്ക് ചെയ്യുക. ഒരു ബ്രാഞ്ച് ടിക്ക് ചെയ്യുന്നത് പിന്നീട് അതിലേക്ക് ചേർക്കുന്നത് ഉൾപ്പെടെ അതിലുള്ള എല്ലാം എടുക്കും — അതിനാൽ അടുത്ത വർഷം സൃഷ്ടിക്കുന്ന ഒരു department സ്വയം എത്തും. ടിക്ക് ചെയ്ത ഒരു ബ്രാഞ്ചിനുള്ളിലെ എന്തെങ്കിലും ഒഴിവാക്കാൻ അൺടിക്ക് ചെയ്യുക.',
