        'mcp_desc' => 'FreeITSM <strong>Model Context Protocol</strong> സംസാരിക്കുന്നു, അതിനാൽ Claude Code അല്ലെങ്കിൽ Claude Desktop പോലുള്ള ഒരു AI അസിസ്റ്റന്റിന് ഇത് വായിക്കാം - പ്രോജക്റ്റുകൾ, തുറന്ന ഇൻസിഡന്റുകൾ, സേവന നില, മാറ്റങ്ങൾ, ആസ്തികൾ എന്നിവയും മറ്റും. ഇത് <strong>വായന മാത്രം</strong> ആണ്, കീയുടെ അനലിസ്റ്റിന് കാണാൻ അനുവാദമുള്ളത് മാത്രമേ കാണൂ: അവരുടെ മൊഡ്യൂളുകളും കീയുടെ കമ്പനികളും. <strong>MCP server</strong> അനുമതിയോടെ താഴെ ഒരു കീ സൃഷ്ടിച്ച് ഈ വിലാസം അസിസ്റ്റന്റിന് നൽകുക. <a href="https://github.com/edmozley/freeitsm/wiki/MCP-Server" target="_blank" rel="noopener">ഗൈഡ്</a> കാണുക.',
        'mcp_claude_code' => 'Claude Code-നായി, ഒരു ടെർമിനലിൽ ഇത് പ്രവർത്തിപ്പിക്കുക (YOUR_KEY-യുടെ സ്ഥാനത്ത് നിങ്ങളുടെ കീ നൽകി):',
        'openapi_desc' => 'മുഴുവൻ API-യുടെയും മെഷീൻ-റീഡബിൾ വിവരണം. ഇത് <strong>Postman</strong> അല്ലെങ്കിൽ <strong>Insomnia</strong>-ലേക്ക് ഇംപോർട്ട് ചെയ്യുക, ഒരു ക്ലയന്റ് ലൈബ്രറി ജനറേറ്റ് ചെയ്യുക, അല്ലെങ്കിൽ ഏതെങ്കിലും OpenAPI ടൂളിന് നൽകുക &mdash; അങ്ങനെ ഓരോ എൻഡ്‌പോയിന്റും കൈകൊണ്ട് ബന്ധിപ്പിക്കേണ്ടി വരില്ല. ഇത് പുതിയതാണോ? <a href="https://github.com/edmozley/freeitsm/wiki/REST-API-OpenAPI" target="_blank" rel="noopener">ഗൈഡ്</a> കാണുക.',
        'view_json' => 'JSON കാണുക',
        'view_yaml' => 'YAML കാണുക',
        'keys' => 'API കീകൾ',
        'keys_desc' => 'ഒരു കീ ഒരു അനലിസ്റ്റായി പ്രവർത്തിക്കുന്നു, അതിന്റെ അനുമതികൾ അനുവദിക്കുന്നത് മാത്രമേ അതിന് ചെയ്യാനാകൂ. പൂർണ്ണമായ കീ സൃഷ്ടിക്കുന്ന സമയത്ത് ഒരിക്കൽ മാത്രം കാണിക്കും.',
