    'webhooks' => [
        'browser_title' => 'വെബ്ഹുക്കുകൾ',
        'title' => 'Webhooks',
        'subtitle' => 'പുറത്തേക്കുള്ള webhooks &mdash; <em>Send a webhook</em> വർക്ക്ഫ്ലോ ആക്ഷൻ ക്യൂവിൽ ചേർക്കുന്നവ &mdash; സ്വയമേവയുള്ള റീട്രൈകളോടെ പശ്ചാത്തലത്തിൽ ഡെലിവർ ചെയ്യുന്നു, അതിനാൽ പതുക്കെയുള്ളതോ പ്രവർത്തിക്കാത്തതോ ആയ ഒരു എൻഡ്‌പോയിന്റ് ഒരു ടിക്കറ്റിനെ ഒരിക്കലും തടഞ്ഞുനിർത്തില്ല. ഡെലിവറി സജ്ജമാക്കിയിട്ടുണ്ടോ എന്നും, ഡെലിവറി ആരോഗ്യത്തിന്റെ ഒരു അവലോകനവും, ഓരോ അഭ്യർത്ഥനയും അതിന്റെ പ്രതികരണവും പരിശോധിക്കാനും ഏതെങ്കിലുമൊന്ന് വീണ്ടും പ്ലേ ചെയ്യാനും കഴിയുന്ന പൂർണ്ണ ലോഗും ഈ പേജ് കാണിക്കുന്നു.',
        'pill_running' => 'ഡെലിവറി വർക്കർ പ്രവർത്തിക്കുന്നു',
        'pill_stale' => 'ഡെലിവറി വർക്കർ വൈകുന്നു',
        'pill_down' => 'ഡെലിവറി വർക്കർ നിലച്ചു',
