        'running_ok' => 'പശ്ചാത്തല വർക്കർ പ്രവർത്തിക്കുന്നു, ക്യൂ ഡെലിവർ ചെയ്യുന്നു.',
        'waiting_one' => '<strong>1</strong> webhook കാത്തിരിക്കുന്നു &mdash; അത് ഒരു മിനിറ്റിനുള്ളിൽ പുറത്തേക്ക് പോകും.',
        'waiting_many' => '<strong>{n}</strong> webhooks കാത്തിരിക്കുന്നു &mdash; അവ ഒരു മിനിറ്റിനുള്ളിൽ പുറത്തേക്ക് പോകും.',
        'nothing_waiting' => 'നിലവിൽ ഒന്നും കാത്തിരിക്കുന്നില്ല.',
        'never_explain' => 'പശ്ചാത്തല ഡെലിവറി വർക്കർ പ്രവർത്തിക്കാൻ ഷെഡ്യൂൾ ചെയ്യുന്നതുവരെ <strong>webhooks അയയ്ക്കില്ല</strong>.',
        'down_explain' => '<strong>webhooks ഇനി അയയ്ക്കുന്നില്ല</strong> &mdash; വർക്കർ അവസാനം പ്രവർത്തിച്ചത് {when}, അത് നിലച്ചതായി തോന്നുന്നു.',
        'stale_explain' => 'വർക്കർ പ്രവർത്തിക്കുന്നുണ്ട്, പക്ഷേ ഷെഡ്യൂളിനേക്കാൾ പിന്നിലാണ് (അവസാന റൺ {when}). ഇത് ഓരോ മിനിറ്റിലും പ്രവർത്തിക്കണം.',
        'queued_one' => '<strong>1</strong> webhook ക്യൂവിൽ കാത്തിരിക്കുന്നു.',
        'queued_many' => '<strong>{n}</strong> webhooks ക്യൂവിൽ കാത്തിരിക്കുന്നു.',
        'step1' => '<strong>ഡെലിവറി വർക്കർ ഓരോ മിനിറ്റിലും പ്രവർത്തിക്കാൻ ഷെഡ്യൂൾ ചെയ്യുക.</strong> സെർവറിൽ, ഒരു ഷെഡ്യൂൾ ചെയ്ത ടാസ്കിൽ നിന്ന് (Windows Task Scheduler) അല്ലെങ്കിൽ cron-ൽ നിന്ന് (Linux) ഈ കമാൻഡ് പ്രവർത്തിപ്പിക്കുക:',
        'step1_http' => 'ഷെല്ലിൽ നിന്ന് PHP പ്രവർത്തിപ്പിക്കാൻ കഴിയുന്നില്ലേ? പകരം HTTP വഴി അത് വിളിക്കുക (ഉദാ. ഒരു ഹോസ്റ്റഡ് cron സേവനത്തിൽ നിന്ന്):',
        'step2' => 'ഇവന്റുകൾ ക്യൂ നിറയ്ക്കാൻ തുടങ്ങേണ്ടതിന് <strong>ഒരു വർക്ക്ഫ്ലോയിലേക്ക് <em>Send a webhook</em> ആക്ഷൻ ചേർക്കുക</strong> &mdash; <a href="{url}">Workflows</a>-ന് കീഴിൽ.',
        'step3' => '<strong>ഈ പേജ് നിരീക്ഷിക്കുക.</strong> വർക്കർ ഒരിക്കൽ പ്രവർത്തിച്ചുകഴിഞ്ഞാൽ, മുകളിലെ നില പച്ചയാകും, ഡെലിവറികൾ താഴെ കാണിക്കും. പൂർണ്ണമായ സജ്ജീകരണ കുറിപ്പുകൾ (Windows &amp; Linux, signature verification) <a href="https://github.com/edmozley/freeitsm/wiki/Workflows" target="_blank" rel="noopener">Workflows വിക്കിയിൽ</a> ഉണ്ട്.',
        'fact_worker' => 'വർക്കർ സ്ക്രിപ്റ്റ്',
        'fact_retry' => 'റീട്രൈ ഷെഡ്യൂൾ',
