        'days' => '{n} ദിവസം',
        'dp_title' => 'ഡാറ്റ സംരക്ഷണം',
        'dp_desc' => 'നിങ്ങളുടെ webhooks-നെ കുറിച്ച് FreeITSM ഡിസ്കിൽ എന്ത് സൂക്ഷിക്കുന്നു, എത്ര കാലം സൂക്ഷിക്കുന്നു.',
        'enc_on_title' => 'Webhook URL-കളും സൈനിംഗ് സീക്രട്ടുകളും സൂക്ഷിക്കുമ്പോൾ എൻക്രിപ്റ്റ് ചെയ്യുന്നു',
        'enc_on_body' => 'വർക്ക്ഫ്ലോയിലും ഡെലിവറി ക്യൂവിലും AES-256-GCM ഉപയോഗിച്ചാണ് സൂക്ഷിക്കുന്നത്. ഒരു webhook URL സ്വയം തന്നെ ഒരു ക്രെഡൻഷ്യലാണ് &mdash; അത് കൈവശമുള്ള ആർക്കും നിങ്ങളുടെ ചാനലിലേക്ക് പോസ്റ്റ് ചെയ്യാം &mdash; ഒരു സന്ദേശം ശരിക്കും നിങ്ങളിൽ നിന്നാണ് വന്നതെന്ന് തെളിയിക്കുന്നത് സൈനിംഗ് സീക്രട്ടാണ്.',
        'enc_off_title' => 'എൻക്രിപ്ഷൻ കീ ഒന്നും ക്രമീകരിച്ചിട്ടില്ല &mdash; webhook URL-കളും സൈനിംഗ് സീക്രട്ടുകളും പ്ലെയിൻ ടെക്സ്റ്റായി സൂക്ഷിക്കുന്നു',
        'enc_off_body' => 'ഒരു എൻക്രിപ്ഷൻ കീ ഫയൽ ഉള്ളപ്പോൾ FreeITSM ഇവ എൻക്രിപ്റ്റ് ചെയ്യും, പക്ഷേ ഈ ഇൻസ്റ്റാളിൽ അതില്ല, അതിനാൽ നിങ്ങളുടെ webhooks പൂർണ്ണമായി പരാജയപ്പെടുത്തുന്നതിന് പകരം അവ ഉള്ളതുപോലെ സേവ് ചെയ്യുന്നു. ഡാറ്റാബേസോ അതിന്റെ ഒരു ബാക്കപ്പോ വായിക്കാൻ കഴിയുന്ന ആർക്കും നിങ്ങളുടെ ചാനലുകളിലേക്ക് പോസ്റ്റ് ചെയ്യാനും നിങ്ങളുടെ സിഗ്നേച്ചറുകൾ വ്യാജമായി ഉണ്ടാക്കാനും കഴിയും. എൻക്രിപ്ഷൻ കീ (<code>ENCRYPTION_KEY_PATH</code>) ക്രമീകരിച്ച ശേഷം, സൂക്ഷിച്ച മൂല്യങ്ങൾ എൻക്രിപ്റ്റ് ചെയ്യാൻ ഓരോ webhook വർക്ക്ഫ്ലോയും വീണ്ടും സേവ് ചെയ്യുക.',
        'ret_label' => 'അയച്ച പേലോഡുകൾ സൂക്ഷിക്കേണ്ട കാലം',
        'ret_none' => 'അവ ഒട്ടും സൂക്ഷിക്കരുത്',
        'ret_1' => '1 ദിവസം',
        'ret_7' => '7 ദിവസം (ശുപാർശ ചെയ്യുന്നു)',
        'ret_30' => '30 ദിവസം',
        'ret_forever' => 'ഡെലിവറി റെക്കോർഡ് നിലനിൽക്കുന്നിടത്തോളം',
        'ret_help' => 'അയച്ച കൃത്യമായ പേലോഡ് ഡെലിവറി ലോഗ് സൂക്ഷിക്കുന്നു. <strong>Full record</strong> ഫോർമാറ്റിൽ അത് ഒരു <strong>മുഴുവൻ ടിക്കറ്റാണ്</strong> &mdash; വിഷയം, അഭ്യർത്ഥിച്ചയാൾ, എല്ലാം &mdash; പ്ലെയിൻ ടെക്സ്റ്റായി ഇവിടെ പകർത്തിയിരിക്കുന്നു. ഇത്രയും ദിവസങ്ങൾക്ക് ശേഷം പേലോഡും പ്രതികരണ ബോഡികളും മായ്ക്കുന്നു, അതേസമയം ഡെലിവറി <em>റെക്കോർഡ്</em> (എൻഡ്‌പോയിന്റ്, നില, സമയം, പിശകുകൾ) മുകളിലെ ലോഗ് നിലനിർത്തൽ ({days} ദിവസം) ആ വരി പൂർണ്ണമായി നീക്കം ചെയ്യുന്നതുവരെ ഓഡിറ്റിനായി സൂക്ഷിക്കുന്നു.',
        'ret_tradeoff' => '<strong>ട്രേഡ്-ഓഫ്:</strong> <em>Replay</em> സൂക്ഷിച്ച പേലോഡ് വീണ്ടും അയയ്ക്കുന്നു, അതിനാൽ പേലോഡ് മായ്ച്ച ഒരു ഡെലിവറി ഇനി റീപ്ലേ ചെയ്യാനാകില്ല. ഒരു പരാജയത്തിന് ശേഷം മണിക്കൂറുകൾക്കുള്ളിലാണ് സാധാരണയായി Replay ഉപയോഗിക്കുന്നത്, ആഴ്ചകൾക്ക് ശേഷമല്ല.',
        'ov_title' => 'അവലോകനം',
        'ov_desc' => 'ഒറ്റനോട്ടത്തിൽ ഡെലിവറി ആരോഗ്യം &mdash; കഴിഞ്ഞ 7 ദിവസം, കൂടാതെ ഏറ്റവും തിരക്കുള്ള എൻഡ്‌പോയിന്റുകളും ഏറ്റവും കൂടുതൽ അയയ്ക്കുന്ന വർക്ക്ഫ്ലോകളും.',
