    'bingo' => [
        'heading' => 'Feature Bingo',
        'intro' => 'മിക്കവരും തങ്ങൾക്കുള്ളതിന്റെ ഒരു ചെറിയ ഭാഗം മാത്രമേ ഉപയോഗിക്കുന്നുള്ളൂ. ഓരോ കാർഡും FreeITSM-ന് ചെയ്യാൻ കഴിയുന്ന ഒരു കാര്യമാണ്, ഇവിടെ സെറ്റപ്പ് ചെയ്യുമ്പോൾ അതിന്റെ നക്ഷത്രം തെളിയും. ഒന്ന് തുറന്ന് അത് എന്താണെന്നും എന്തുകൊണ്ട് ചെയ്യേണ്ടതാണെന്നും എവിടെ സെറ്റപ്പ് ചെയ്യണമെന്നും കാണുക. നിങ്ങൾ ഒരിക്കലും ഉപയോഗിക്കാത്തത് Not for us എന്ന് അടയാളപ്പെടുത്തുക, അത് സ്കോറിൽ നിന്ന് ഒഴിവാകും.',
        'needs_verify' => 'കാർഡുകൾ Not for us എന്ന് അടയാളപ്പെടുത്താൻ System → Database Verification പ്രവർത്തിപ്പിക്കുക. നക്ഷത്രങ്ങൾ ഇപ്പോൾ തന്നെ പ്രവർത്തിക്കുന്നു.',
