    'managers' => [
        'heading' => 'മാനേജർമാർ',
        'intro' => 'സെൽഫ്-സർവീസ് പോർട്ടലിൽ, തങ്ങൾ മാനേജ് ചെയ്യുന്നവർ ഉന്നയിച്ച ടിക്കറ്റുകൾ കാണാൻ കഴിയുന്ന ഒരാളാണ് മാനേജർ - ഉദാഹരണത്തിന് ഒരു വകുപ്പ് മേധാവി. അവർക്ക് പോർട്ടലിൽ ഒരു <strong>Team tickets</strong> ടാബ് ലഭിക്കും. സർവീസ് ഡെസ്കിനെ ഇത് ബാധിക്കില്ല.',
        'needs_verify' => 'ആദ്യം System → Database Verification പ്രവർത്തിപ്പിക്കുക. അത് പ്രവർത്തിപ്പിക്കുന്നതുവരെ, രഹസ്യ ടിക്കറ്റുകളെ വേർതിരിച്ചറിയാൻ കഴിയാത്തതിനാൽ ഇവിടെ എന്ത് സജ്ജമാക്കിയാലും മാനേജർമാർ ഓഫ് ആയിരിക്കും.',
        'on_heading' => 'പോർട്ടലിലെ മാനേജർമാർ',
