        'enabled_desc' => 'നിങ്ങൾ ഓൺ ആക്കുന്നതുവരെ ഓഫ് ആണ്. ഇത് ഓഫ് ആയിരിക്കുമ്പോൾ താഴെയുള്ള ഒന്നിനും ഫലമില്ല.',
        'source_heading' => 'മാനേജർമാർ എവിടെ നിന്ന് വരുന്നു',
        'source_desc' => 'രണ്ട് ഉറവിടങ്ങൾ, രണ്ടും ഒരേസമയം. മാനേജ്മെന്റ് ലൈനുകൾ ഓരോ മാനേജർക്കും Tickets → Users അല്ലെങ്കിൽ Assets → Users-ലെ Manager access ബട്ടൺ ഉപയോഗിച്ച് സജ്ജമാക്കുന്നു.',
        'directory' => 'ഓരോ വ്യക്തിയുടെയും Manager ഫീൽഡ് ഉപയോഗിക്കുക',
        'directory_desc' => 'ഒരാളുടെ Manager ആയി സജ്ജമാക്കിയിരിക്കുന്നവർക്ക് - കൈകൊണ്ടായാലും ഡയറക്ടറിയിൽ നിന്നായാലും - അവരുടെ ടിക്കറ്റുകൾ കാണാം.',
