        'depth_all' => 'അവർക്ക് താഴെയുള്ള എല്ലാവരും, ഏറ്റവും താഴെ വരെ',
        'can_heading' => 'മാനേജർമാർക്ക് എന്തു ചെയ്യാം',
        'can_desc' => 'മാനേജർമാർക്ക് എപ്പോഴും അവരുടെ ടീമിന്റെ ടിക്കറ്റുകൾ വായിക്കാം. മറ്റെന്തൊക്കെ ചെയ്യാമെന്ന് ഓരോ ടിക്കറ്റിലും അവരെ അറിയിക്കും.',
