        'can_close' => 'അവരുടെ ടീമിന്റെ ടിക്കറ്റുകൾ അടയ്ക്കുക',
        'conf_heading' => 'രഹസ്യ ടിക്കറ്റുകൾ',
        'conf_desc' => 'രഹസ്യം എന്ന് അടയാളപ്പെടുത്തിയ ടിക്കറ്റിൽ ഒരു മാനേജർ എന്ത് കാണുന്നു - HR-ലേക്ക് അയച്ച ഒരു രോഗനിർണയം, അല്ലെങ്കിൽ മാനേജർക്കെതിരെ തന്നെയുള്ള ഒരു പരാതി.',
        'conf_none' => 'ഒന്നും തന്നെയില്ല (ശുപാർശ ചെയ്യുന്നത്)',
        'conf_none_desc' => 'ടിക്കറ്റ് പൂർണ്ണമായും ഒഴിവാക്കും. അങ്ങനെ ഒന്നുണ്ടെന്ന് പോലും മാനേജർക്ക് അറിയാനാകില്ല.',
        'conf_stub' => 'ഒരു രഹസ്യ ടിക്കറ്റ് ഉണ്ടെന്ന വസ്തുത',
        'conf_stub_desc' => '"Confidential ticket" എന്ന പേരിൽ അതിന്റെ നമ്പറും നിലയും മാത്രം പട്ടികപ്പെടുത്തും, അതിലെ ഉള്ളടക്കം ഇല്ല. ഇത് മാത്രം ആരോ എന്തോ സ്വകാര്യമായി ഉന്നയിച്ചെന്ന് മാനേജറെ അറിയിച്ചേക്കാം എന്ന് ഓർക്കുക.',
        'conf_all' => 'എല്ലാം',
