        'notify_heading' => 'പുതിയ ടിക്കറ്റുകളെക്കുറിച്ച് മാനേജർമാരെ അറിയിക്കൽ',
        'notify_desc' => 'ഒരു മാനേജരുടെ ടീമിലെ ആരെങ്കിലും ടിക്കറ്റ് ഉന്നയിക്കുമ്പോൾ - എന്നാൽ രഹസ്യ ടിക്കറ്റ് പോലെ മാനേജർക്ക് തുറക്കാൻ അനുവാദമില്ലാത്തത് ഒരിക്കലുമില്ല.',
