        'notify_bell_desc' => 'പോർട്ടൽ ഹെഡറിൽ ഓരോ മാനേജർക്കുമുള്ള ബെല്ലിലേക്ക് - അനലിസ്റ്റുകൾക്കുള്ള അതേ ബെൽ. ഇമെയിലിനേക്കാൾ ശാന്തം: അവർ അടുത്ത തവണ സൈൻ ഇൻ ചെയ്യുമ്പോൾ അത് അവിടെ ഉണ്ടാകും.',
