        'leavers_desc' => 'സ്ഥിരമായി ഓൺ ആണ്, അതിനാൽ ഒരാൾ വിടുമ്പോൾ തുറന്നിരിക്കുന്ന ടിക്കറ്റിന്റെ മേൽനോട്ടം തുടരും. വിട്ടുപോയ മാനേജർക്ക് എപ്പോഴും ആക്സസ് നഷ്ടപ്പെടും.',
