        'overview_heading' => 'മാനേജർമാർ',
        'overview_desc' => 'ആരെയെങ്കിലും മാനേജ് ചെയ്യുന്ന എല്ലാവരും, അവർക്ക് എത്ര പേരെ കാണാനാകും എന്നതോടെ - മാനേജർമാർ ഓൺ ആയിരുന്നെങ്കിൽ എന്ന മട്ടിൽ കണക്കാക്കിയത്, അതിനാൽ ഓൺ ആക്കുന്നതിന് മുമ്പ് പരിശോധിക്കാം.',
