    'self_service' => [
        'heading' => 'സെൽഫ്-സർവീസ് പോർട്ടൽ',
        'intro' => 'ടിക്കറ്റ് രജിസ്റ്റർ ചെയ്യുന്ന ആളുകൾക്ക് പോർട്ടൽ എങ്ങനെ കാണപ്പെടുന്നു, അവർക്ക് അതിൽ എന്തൊക്കെ ചെയ്യാം എന്നത്. മിക്ക സ്ഥാപനങ്ങളിലും ഒരു കസ്റ്റമർ കാണുന്ന FreeITSM-ന്റെ ഏക ഭാഗം പോർട്ടലാണ്; അതുകൊണ്ട് ബാക്കിയുള്ളതിൽ നിന്ന് വേറിട്ട് ബ്രാൻഡ് ചെയ്യാൻ യോഗ്യമായ ഒരേയൊരു സ്ക്രീനും അതാണ്.',
        'appearance_heading' => 'രൂപഭാവം',
        'appearance_desc' => 'ഇവ പോർട്ടലിന് മാത്രം ബാധകമാണ്. <strong>System &rarr; Branding</strong> എന്നതിലെ ലോഗോ ഇപ്പോഴും ആപ്പ്, ലോഗിൻ സ്ക്രീൻ, നിങ്ങളുടെ ഇമെയിലുകൾ എന്നിവയ്ക്ക് ബാധകമാണ്.',
        'logo_label' => 'പോർട്ടൽ ലോഗോ',
        'logo_desc' => 'പോർട്ടലിനായി മറ്റൊരു ലോഗോ &mdash; സർവീസ് ഡെസ്ക് വേറൊരു പേരിൽ പ്രവർത്തിക്കുമ്പോൾ, അല്ലെങ്കിൽ ഇരുണ്ട ആപ്പ് ഹെഡറിനായി വരച്ച പ്രധാന ലോഗോ വെളുത്ത പേജിൽ മോശമായി കാണപ്പെടുമ്പോൾ ഇത് ഉപകാരപ്പെടും. പ്രധാന ലോഗോ ഉപയോഗിക്കാൻ ഇത് ശൂന്യമായി വിടുക.',
        'logo_remove' => 'നീക്കം ചെയ്യുക',
